package com.friendscape;

import java.awt.Color;
import lombok.AllArgsConstructor;
import lombok.Getter;
import net.runelite.client.ui.ColorScheme;

/** What an Event card says about the player's part in it (SPEC 10.3), with its dot colour. */
@Getter
@AllArgsConstructor
enum CardState
{
	TRACKING(ColorScheme.PROGRESS_COMPLETE_COLOR),
	/** An identity mismatch is held: progress counts nowhere until it is settled. */
	ATTENTION(ColorScheme.PROGRESS_INPROGRESS_COLOR),
	/** Taken off the Roster mid-Event. */
	NOT_ON_ROSTER(new Color(0x4D9DE0)),
	/** Muted on this install; the server is never told. */
	LEFT(ColorScheme.MEDIUM_GRAY_COLOR),
	/** A Series Event whose Vote is open: the card carries the Ballot. */
	VOTING(new Color(0xB57EDC)),
	/** Published with no start and end set yet. */
	NOT_SCHEDULED(ColorScheme.LIGHT_GRAY_COLOR),
	ENDED(ColorScheme.LIGHT_GRAY_COLOR),
	FINAL(ColorScheme.BRAND_ORANGE);

	private final Color color;
}

package com.friendscape;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import java.util.function.BooleanSupplier;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;

/**
 * One Live Event's Codeword in game, so a screenshot taken for a manual upload carries it (SPEC
 * 10.3): the Codeword, then the local clock in UTC. Named by Event number, so a dragged position
 * sticks to its Event.
 */
class CodewordOverlay extends OverlayPanel
{
	private static final DateTimeFormatter TIMESTAMP =
		DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm 'UTC'", Locale.ENGLISH).withZone(ZoneOffset.UTC);
	/** The space between the Codeword and the timestamp. */
	private static final int GAP = 10;

	private final int number;
	private final BooleanSupplier shown;
	private final FriendscapeConfig config;
	private volatile String codeword = "";

	CodewordOverlay(Plugin plugin, int number, BooleanSupplier shown, FriendscapeConfig config)
	{
		super(plugin);
		this.number = number;
		this.shown = shown;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public String getName()
	{
		return "friendscape-codeword-" + number;
	}

	String getCodeword()
	{
		return codeword;
	}

	void setCodeword(String codeword)
	{
		this.codeword = codeword;
	}

	/** The overlay's clock: UTC to the minute, e.g. {@code 2026-11-03 12:05 UTC}. */
	static String timestamp(Instant now)
	{
		return TIMESTAMP.format(now);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!shown.getAsBoolean())
		{
			return null;
		}
		String current = codeword;
		String time = config.codewordTimestamp() ? timestamp(Instant.now()) : "";
		// Wide enough for one line: the default panel width would wrap a long Codeword
		FontMetrics metrics = graphics.getFontMetrics();
		int width = metrics.stringWidth(current) + (time.isEmpty() ? 0 : GAP + metrics.stringWidth(time))
			+ 2 * ComponentConstants.STANDARD_BORDER;
		panelComponent.setPreferredSize(new Dimension(width, 0));
		panelComponent.getChildren().add(LineComponent.builder()
			.left(current)
			.leftColor(config.codewordColor())
			.right(time)
			.rightColor(config.timestampColor())
			.build());
		return super.render(graphics);
	}
}

package com.friendscape;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.IntFunction;
import net.runelite.client.ui.overlay.Overlay;

/**
 * The Codeword overlays in game (SPEC 10.3): one per Live card with a Codeword the player has not
 * hidden. Adds and removes them as cards come and go; called from any thread.
 */
class CodewordOverlays
{
	private final Consumer<Overlay> add;
	private final Consumer<Overlay> remove;
	private final IntFunction<CodewordOverlay> create;
	/** By Event number. */
	private final Map<Integer, CodewordOverlay> overlays = new HashMap<>();
	/** Set by {@link #close}: a late refresh must not add overlays back once the plugin stops. */
	private boolean closed;

	CodewordOverlays(Consumer<Overlay> add, Consumer<Overlay> remove, IntFunction<CodewordOverlay> create)
	{
		this.add = add;
		this.remove = remove;
		this.create = create;
	}

	/** Codewords by Event number, in card order: each card that carries one, less those hidden. */
	static Map<Integer, String> wanted(List<EventCard> cards, Set<Integer> hidden)
	{
		Map<Integer, String> wanted = new LinkedHashMap<>();
		for (EventCard card : cards)
		{
			if (card.getCodeword() != null && !hidden.contains(card.getNumber()))
			{
				wanted.put(card.getNumber(), card.getCodeword());
			}
		}
		return wanted;
	}

	/** Shows exactly these Codewords, keeping each overlay that stays so its position holds. */
	synchronized void show(Map<Integer, String> codewords)
	{
		if (closed)
		{
			return;
		}
		overlays.entrySet().removeIf(entry ->
		{
			boolean gone = !codewords.containsKey(entry.getKey());
			if (gone)
			{
				remove.accept(entry.getValue());
			}
			return gone;
		});
		codewords.forEach((number, codeword) ->
		{
			CodewordOverlay overlay = overlays.get(number);
			if (overlay == null)
			{
				overlay = create.apply(number);
				overlay.setCodeword(codeword);
				overlays.put(number, overlay);
				add.accept(overlay);
			}
			else
			{
				overlay.setCodeword(codeword);
			}
		});
	}

	/** Removes every overlay for good. */
	synchronized void close()
	{
		show(Map.of());
		closed = true;
	}

	/** The overlay showing an Event's Codeword, or null. */
	synchronized CodewordOverlay overlay(int number)
	{
		return overlays.get(number);
	}
}

package com.friendscape;

import java.awt.Color;
import lombok.AllArgsConstructor;
import lombok.Getter;
import net.runelite.client.ui.ColorScheme;

@Getter
@AllArgsConstructor
enum ConnectionStatus
{
	OFF("Sending is off", ColorScheme.LIGHT_GRAY_COLOR),
	LOGGED_OUT("Log in to start tracking", ColorScheme.LIGHT_GRAY_COLOR),
	WORLD_NOT_TRACKED("Not tracked on Leagues or special worlds", ColorScheme.PROGRESS_INPROGRESS_COLOR),
	CONNECTING("Connecting", ColorScheme.LIGHT_GRAY_COLOR),
	CONNECTED("Connected", ColorScheme.PROGRESS_COMPLETE_COLOR),
	UNREACHABLE("Server unreachable, retrying", ColorScheme.LIGHT_GRAY_COLOR);

	private final String text;
	private final Color color;
}

package com.friendscape;

import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import lombok.Value;
import lombok.With;
import lombok.extern.slf4j.Slf4j;

/**
 * The server's answer to discovery: every Event that rosters the logged-in character, with its
 * phase, the player's Roster entry state and standing. The plugin's cards come from it alone.
 */
@Slf4j
@Value
class DiscoveryResponse
{
	/** A Finalized Event's card goes this long after Finalize, as the server stops listing it. */
	static final Duration FINALIZED_VISIBLE = Duration.ofDays(7);
	/**
	 * After an Event's end, how long a Reading may still be its end Reading: the server takes one up
	 * to a minute after end, plus the plugin's retries while the server's clock lags.
	 */
	static final Duration END_READING_WINDOW = Duration.ofMinutes(2);

	static final String LIVE = "live";
	static final String SCHEDULED = "scheduled";
	static final String PUBLISHED = "published";
	static final String ENDED = "ended";
	static final String FINALIZED = "finalized";
	static final String HELD = "held";
	static final String REMOVED = "removed";

	String rsn;
	/** Empty when no Roster has the character: the empty state. */
	List<DiscoveredEvent> events;

	@Value
	static class DiscoveredEvent
	{
		/** The Event number: six digits, 100000 to 999999. */
		int number;
		String name;
		/** {@code bingo}, {@code sotw} or {@code botw}. */
		String format;
		/** {@code published}, {@code scheduled}, {@code live}, {@code ended} or {@code finalized}. */
		String phase;
		String startsAt;
		String endsAt;
		int graceWindowSeconds;
		String finalizedAt;
		/** {@code on_roster}, {@code held} or {@code removed}. */
		String entry;
		List<TeamSize> teams;
		/** Null without a metric, or while no Team counts the entry. */
		Standing standing;
		/** The player's Submissions here still waiting for a screenshot; absent from older servers. */
		int needsEvidence;
		/** What Tiles open for the player's Teams look for; null when nothing is open. */
		Watch watch;
		/** A bingo Event's mini board with every Team's standing; null on a metric Event or older server. */
		Board board;
		/** A Series Event's Vote while votes are taken; null otherwise, and from older servers. */
		@With
		Vote vote;
		/**
		 * The Codeword while the Event is Live with it on; null otherwise, and from older servers. Held
		 * and removed entries carry it too: the card decides whether it shows.
		 */
		String codeword;
	}

	/** A Series Event's Vote as the card's picker shows it (SPEC 10.3): counts only, never who voted. */
	@Value
	static class Vote
	{
		/** The Any mode tally shows this many voted Candidates, then how many more have votes. */
		static final int TALLY_TOP = 3;

		String closesAt;
		/** Any mode: every skill or boss, offered as a dropdown under the top voted. */
		boolean open;
		/** In Ballot order. */
		List<VoteCandidate> candidates;
		/** The Candidate id the player voted for from the plugin; null until then. */
		Integer choice;

		List<VoteCandidate> candidates()
		{
			return candidates == null ? List.of() : candidates;
		}

		/**
		 * Any mode's tally: the top voted Candidates by count, ties in Ballot order, then
		 * "+N more with votes"; "No votes yet" when none has any.
		 */
		List<String> tally()
		{
			List<VoteCandidate> voted = new ArrayList<>();
			for (VoteCandidate candidate : candidates())
			{
				if (candidate.votes() > 0)
				{
					voted.add(candidate);
				}
			}
			if (voted.isEmpty())
			{
				return List.of("No votes yet");
			}
			// A stable sort keeps Ballot order among ties
			voted.sort(Comparator.comparingInt(VoteCandidate::votes).reversed());
			List<String> lines = new ArrayList<>();
			for (VoteCandidate candidate : voted.subList(0, Math.min(TALLY_TOP, voted.size())))
			{
				lines.add(candidate.getName() + ": " + candidate.votes());
			}
			if (voted.size() > TALLY_TOP)
			{
				lines.add("+" + (voted.size() - TALLY_TOP) + " more with votes");
			}
			return lines;
		}
	}

	@Value
	static class VoteCandidate
	{
		/** The Ballot place, from 1: what a vote names. */
		int id;
		/** What the Candidate measures: a skill or boss name. */
		String name;
		/** Null shows no picture. */
		TileIcon icon;
		/** Absent in Any mode on a Candidate nobody voted for. */
		Integer count;
		/** On Cooldown: shown, never votable. */
		boolean cooling;

		int votes()
		{
			return count == null ? 0 : count;
		}

		/** The dropdown's line. */
		@Override
		public String toString()
		{
			return cooling ? name + " (On Cooldown)" : name;
		}
	}

	/** A bingo Event's board as the mini board shows it (SPEC 10.3): what the website shows. */
	@Value
	static class Board
	{
		/** Squares per side. */
		int size;
		/** Stored Tiles only; a position without one shows empty. */
		List<BoardTile> tiles;
		/** Every Team, in standings order. */
		List<BoardTeam> teams;

		/** The Tile at a number, or null for an empty position. */
		BoardTile tile(int number)
		{
			for (BoardTile tile : tiles == null ? List.<BoardTile>of() : tiles)
			{
				if (tile.getNumber() == number)
				{
					return tile;
				}
			}
			return null;
		}

		List<BoardTeam> teams()
		{
			return teams == null ? List.of() : teams;
		}

		/** The Teams the player is on, best first. */
		List<BoardTeam> mine()
		{
			List<BoardTeam> mine = new ArrayList<>();
			for (BoardTeam team : teams())
			{
				if (team.isMine())
				{
					mine.add(team);
				}
			}
			return mine;
		}

		/** Squares per side; 0 for a board too broken to draw. */
		int side()
		{
			return Math.max(0, size);
		}
	}

	@Value
	static class BoardTile
	{
		/** From 1: position + 1, as the website names it. */
		int number;
		String name;
		int tiers;
		/** Null shows the Tile number. */
		TileIcon icon;
	}

	/** The first Requirement's picture: an item sprite, a boss icon or a skill icon. */
	@Value
	static class TileIcon
	{
		static final String ITEM = "item";
		static final String KC = "kc";
		static final String XP = "xp";

		String kind;
		/** For {@code item}: a canonical item id. */
		int itemId;
		/** For {@code kc}: the activity as RuneLite's hiscores name it. */
		String name;
		/** For {@code xp}: the skill, e.g. {@code slayer}. */
		String skill;
	}

	@Value
	static class BoardTeam
	{
		/** The Team number within the Event: Team links and the remembered Team use it. */
		int team;
		String name;
		int rank;
		/** How many Teams the Event ranks. */
		int of;
		int points;
		/** The player is on it now. */
		boolean mine;
		/** One per position, in order. */
		List<TeamTile> tiles;

		/** The highest Tier reached at a position, from 1; 0 when none is or out of range. */
		int tier(int position)
		{
			if (tiles == null || position >= tiles.size() || tiles.get(position).getTier() == null)
			{
				return 0;
			}
			return tiles.get(position).getTier();
		}
	}

	@Value
	static class TeamTile
	{
		static final String COMPLETE = "complete";
		static final String FREE = "free";
		static final String EMPTY = "empty";

		/** {@code empty}, {@code free}, {@code open} or {@code complete}. */
		String state;
		/** The highest Tier reached, from 1; null while none is. */
		Integer tier;
		/** 0 to 1: 1 when complete, else progress toward the next Tier. */
		double fill;
	}

	/**
	 * The open-Tile watch list (SPEC 10.3): the union over the player's Teams. Hidden Tiles are
	 * never in it, as the server redacts them.
	 */
	@Value
	static class Watch
	{
		List<WatchedItem> items;
		/** Some open Tile counts new collection log slots, whatever the item. */
		boolean clogSlots;
	}

	@Value
	static class WatchedItem
	{
		/** A canonical item id, as {@code ItemManager.canonicalize} gives it. */
		int id;
		/** The name chat lines use for it. */
		String name;
	}

	@Value
	static class TeamSize
	{
		String name;
		int size;
	}

	@Value
	static class Standing
	{
		/** The player's own gain since Baseline. */
		long gain;
		/** Each of the player's Teams, best first. */
		List<TeamStanding> teams;
	}

	@Value
	static class TeamStanding
	{
		/** The Team name, or for a Team of one its player's RSN. */
		String name;
		boolean solo;
		int rank;
		/** How many Teams the Event ranks. */
		int of;
		long gain;
	}

	/** The Events, empty when an older or broken answer has none. */
	List<DiscoveredEvent> events()
	{
		return events == null ? List.of() : events;
	}

	/** This answer with the Vote of Event {@code number} swapped for one a vote answered. */
	DiscoveryResponse withVote(int number, Vote vote)
	{
		List<DiscoveredEvent> swapped = new ArrayList<>();
		for (DiscoveredEvent event : events())
		{
			swapped.add(event.getNumber() == number ? event.withVote(vote) : event);
		}
		return new DiscoveryResponse(rsn, swapped);
	}

	/** Event names by Event number, for chat lines. */
	Map<Integer, String> eventNames()
	{
		Map<Integer, String> names = new HashMap<>();
		for (DiscoveredEvent event : events())
		{
			names.put(event.getNumber(), event.getName());
		}
		return names;
	}

	/**
	 * Until when each Event may still count a queued Submission: its end plus Grace window, or
	 * null while it has no end. An Event missing here no longer has a card.
	 */
	Map<Integer, Instant> keepUntil()
	{
		Map<Integer, Instant> keepUntil = new HashMap<>();
		for (DiscoveredEvent event : events())
		{
			Instant endsAt = parse(event, event.getEndsAt());
			keepUntil.put(event.getNumber(), endsAt == null ? null : endsAt.plusSeconds(event.getGraceWindowSeconds()));
		}
		return keepUntil;
	}

	/**
	 * One card per Event, less Finalized ones past their week: live first, then Voting (soonest close
	 * first), scheduled, not scheduled yet, ended, Finalized, and last those left or off the Roster,
	 * in the server's order within each. {@code queued} holds this install's Submissions by Event number.
	 */
	List<EventCard> cards(Set<Integer> left, Map<Integer, EventCard.Queued> queued, Instant now, ZoneId zone)
	{
		Map<DiscoveredEvent, CardBucket> buckets = new IdentityHashMap<>();
		Map<DiscoveredEvent, Instant> closes = new IdentityHashMap<>();
		for (DiscoveredEvent event : events())
		{
			CardBucket bucket = CardBucket.of(event, left);
			buckets.put(event, bucket);
			closes.put(event, bucket == CardBucket.VOTING ? closesAt(event) : Instant.MIN);
		}
		List<DiscoveredEvent> ordered = new ArrayList<>(events());
		// A stable sort keeps the server's order within each bucket
		ordered.sort(Comparator.<DiscoveredEvent, CardBucket>comparing(buckets::get).thenComparing(closes::get));
		List<EventCard> cards = new ArrayList<>();
		for (DiscoveredEvent event : ordered)
		{
			Instant finalizedAt = parse(event, event.getFinalizedAt());
			if (finalizedAt != null && !now.isBefore(finalizedAt.plus(FINALIZED_VISIBLE)))
			{
				continue;
			}
			cards.add(EventCard.of(event, left.contains(event.getNumber()),
				queued.getOrDefault(event.getNumber(), EventCard.Queued.NONE), zone));
		}
		return cards;
	}

	/** Where a card sorts (SPEC 10.3), in declaration order. */
	private enum CardBucket
	{
		LIVE, VOTING, SCHEDULED, NOT_SCHEDULED, ENDED, FINALIZED, LEFT_OR_REMOVED;

		static CardBucket of(DiscoveredEvent event, Set<Integer> left)
		{
			if (left.contains(event.getNumber()) || REMOVED.equals(event.getEntry()))
			{
				return LEFT_OR_REMOVED;
			}
			switch (event.getPhase() == null ? "" : event.getPhase())
			{
				case PUBLISHED:
					return event.getVote() != null ? VOTING : NOT_SCHEDULED;
				case DiscoveryResponse.SCHEDULED:
					return SCHEDULED;
				case DiscoveryResponse.ENDED:
					return ENDED;
				case DiscoveryResponse.FINALIZED:
					return FINALIZED;
				default:
					// Live, and any phase a newer server adds, which may well be running
					return LIVE;
			}
		}
	}

	/** A Voting card's close, for ordering; an unreadable one sorts last among them. */
	private static Instant closesAt(DiscoveredEvent event)
	{
		Instant closesAt = parse(event, event.getVote().getClosesAt());
		return closesAt == null ? Instant.MAX : closesAt;
	}

	/**
	 * Whether a Reading could count anywhere: some Event not left, still on its Roster, and not over
	 * (an Event that just ended still takes its end Reading). A held entry wants them too: its
	 * Readings settle the identity check.
	 */
	boolean wantsReadings(Set<Integer> left, Instant now)
	{
		for (DiscoveredEvent event : events())
		{
			if (left.contains(event.getNumber()) || REMOVED.equals(event.getEntry())
				|| FINALIZED.equals(event.getPhase()))
			{
				continue;
			}
			if (ENDED.equals(event.getPhase()))
			{
				Instant endsAt = parse(event, event.getEndsAt());
				if (endsAt == null || !now.isBefore(endsAt.plus(END_READING_WINDOW)))
				{
					continue;
				}
			}
			return true;
		}
		return false;
	}

	/**
	 * The Events in the Live phase, left or off the Roster too: those whose per-Event overlay
	 * choices are kept (SPEC 10.3), so a Leave and Rejoin keeps them.
	 */
	Set<Integer> liveNumbers()
	{
		Set<Integer> live = new TreeSet<>();
		for (DiscoveredEvent event : events())
		{
			if (LIVE.equals(event.getPhase()))
			{
				live.add(event.getNumber());
			}
		}
		return live;
	}

	/** The discovered Events the player left: what a Reading names as muted. Sorted, for the wire. */
	Set<Integer> muted(Set<Integer> left)
	{
		Set<Integer> muted = new TreeSet<>();
		for (DiscoveredEvent event : events())
		{
			if (left.contains(event.getNumber()))
			{
				muted.add(event.getNumber());
			}
		}
		return muted;
	}

	/**
	 * The Events not left, with the status a Reading would answer for each: what schedules the start
	 * and end Readings, so an idle player still sends the start Reading of an Event Scheduled after
	 * login. Mirrors core {@code readingStatus}.
	 */
	ReadingsResponse asReadings(Set<Integer> left)
	{
		List<ReadingsResponse.EventReading> readings = new ArrayList<>();
		for (DiscoveredEvent event : events())
		{
			if (!left.contains(event.getNumber()))
			{
				readings.add(new ReadingsResponse.EventReading(event.getNumber(), readingStatus(event),
					event.getStartsAt(), event.getEndsAt()));
			}
		}
		return new ReadingsResponse(rsn, readings);
	}

	private static String readingStatus(DiscoveredEvent event)
	{
		if (REMOVED.equals(event.getEntry()))
		{
			return ReadingsResponse.NOT_ON_ROSTER;
		}
		if (ENDED.equals(event.getPhase()) || FINALIZED.equals(event.getPhase()))
		{
			return ReadingsResponse.ENDED;
		}
		if (HELD.equals(event.getEntry()))
		{
			return ReadingsResponse.HELD;
		}
		return LIVE.equals(event.getPhase()) ? ReadingsResponse.COUNTED : ReadingsResponse.NOT_STARTED;
	}

	/** An ISO 8601 time from the server, or null when absent or unreadable (logged). */
	static Instant parse(DiscoveredEvent event, String at)
	{
		if (at == null)
		{
			return null;
		}
		try
		{
			return Instant.parse(at);
		}
		catch (DateTimeParseException e)
		{
			log.warn("Ignoring Event {} with an unreadable time {}", event.getNumber(), at);
			return null;
		}
	}
}

package com.friendscape;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;
import net.runelite.client.util.Text;

/**
 * Reads the chat lines behind clog and pet Submissions (SPEC 10.2). They name items, never ids,
 * and each depends on a game setting: the collection log chat notification, and for pets
 * "Untradeable loot notifications", whose line names the pet after the pet line.
 */
final class DropMessages
{
	enum Kind
	{
		/** A new collection log slot, by item name. */
		CLOG_SLOT,
		/** An untradeable item dropped, by name: names a pet just after {@link #PET}. */
		UNTRADEABLE,
		/** A pet arrived, following or in the backpack; the line does not say which. */
		PET
	}

	@Value
	static class Line
	{
		Kind kind;
		/** Null for {@link Kind#PET}. */
		String name;
	}

	private static final Pattern CLOG = Pattern.compile("New item added to your collection log: (.+)");
	private static final Pattern UNTRADEABLE = Pattern.compile("Untradeable drop: (.+)");
	// A duplicate pet ("would have been followed...") never arrives, so it is not a drop
	private static final String PET_FOLLOWING = "You have a funny feeling like you're being followed.";
	private static final String PET_BACKPACK = "You feel something weird sneaking into your backpack.";

	private DropMessages()
	{
	}

	/** The drop a game message reports, or null for any other line. */
	static Line parse(String message)
	{
		String text = Text.removeTags(message).trim();
		if (text.equals(PET_FOLLOWING) || text.equals(PET_BACKPACK))
		{
			return new Line(Kind.PET, null);
		}
		Matcher clog = CLOG.matcher(text);
		if (clog.matches())
		{
			return new Line(Kind.CLOG_SLOT, clog.group(1).trim());
		}
		Matcher untradeable = UNTRADEABLE.matcher(text);
		if (untradeable.matches())
		{
			return new Line(Kind.UNTRADEABLE, untradeable.group(1).trim());
		}
		return null;
	}
}

package com.friendscape;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import lombok.Value;

/** One Event card as the panel shows it, and the overlay while live (SPEC 10.3): state, detail line and standing. */
@Value
class EventCard
{
	private static final DateTimeFormatter STARTS = DateTimeFormatter.ofPattern("d MMM HH:mm", Locale.ENGLISH);
	/** Larger boards show only the standing line and "Open board" (SPEC 10.3). */
	static final int MAX_MINI_BOARD = 7;
	static final String OPEN_BOARD = "Open board";
	static final String OPEN_EVENT_PAGE = "Open event page";

	/** The Event number. */
	int number;
	String name;
	CardState state;
	/** The line under the name: what the state means for the player. */
	String detail;
	/** The standing line, one per Team, then the player's own gain when on a real Team. */
	List<String> standing;
	/** Lines that ask something of the player: uploads, and Submissions queued or pushed out. */
	List<String> notes;
	/** The best Team's rank for the overlay, e.g. {@code 2nd/4}; empty without a standing. */
	String rank;
	/** A bingo Event's board; null on a metric Event. */
	DiscoveryResponse.Board board;
	/** The label of the link to the website: "Open board" for a board too large to draw, else "Open event page". */
	String link;
	/** Something here waits for a screenshot upload on the website. */
	boolean upload;
	/** An identity mismatch is held here: the card offers "Report to Friendscape" (SPEC 10.3). */
	boolean report;
	/** Live, still on the Roster and not left: the only cards the overlay shows. */
	boolean live;
	/** The open Vote the card's picker shows; null unless Voting. */
	DiscoveryResponse.Vote vote;
	/** The Event is Finalized: nothing left to Leave or Rejoin (SPEC 10.3). */
	boolean finalized;
	/** The Codeword its overlay shows while live; null when there is none to show (SPEC 10.3). */
	String codeword;

	/** This install's Submissions for the Event (SPEC 10.5): what the server does not know of. */
	@Value
	static class Queued
	{
		static final Queued NONE = new Queued(0, 0);

		/** Still in the send queue. */
		int waiting;
		/** Pushed out of the full queue this session, for the player to upload by hand. */
		int pushedOut;
	}

	boolean isLeft()
	{
		return state == CardState.LEFT;
	}

	static EventCard of(DiscoveryResponse.DiscoveredEvent event, boolean left, Queued queued, ZoneId zone)
	{
		CardState state = state(event, left);
		DiscoveryResponse.Board board = event.getBoard();
		boolean bingo = board != null;
		List<String> standing = List.of();
		String rank = "";
		if (bingo && started(event))
		{
			standing = bingoStanding(board);
			rank = bingoRank(board);
		}
		else if (hasStanding(event))
		{
			standing = standing(event);
			rank = rank(event.getStanding());
		}
		boolean upload = (state == CardState.ATTENTION && event.getNeedsEvidence() > 0) || queued.getPushedOut() > 0;
		boolean report = state == CardState.ATTENTION && DiscoveryResponse.HELD.equals(event.getEntry());
		boolean live = DiscoveryResponse.LIVE.equals(event.getPhase()) && !left
			&& !DiscoveryResponse.REMOVED.equals(event.getEntry());
		return new EventCard(event.getNumber(), event.getName(), state, detail(event, state, zone), standing,
			notes(queued), rank, board, bingo && !drawn(board) ? OPEN_BOARD : OPEN_EVENT_PAGE, upload, report, live,
			state == CardState.VOTING ? event.getVote() : null, DiscoveryResponse.FINALIZED.equals(event.getPhase()),
			live ? event.getCodeword() : null);
	}

	/** The mini board draws up to 7x7; larger ones are left to the website. */
	static boolean drawn(DiscoveryResponse.Board board)
	{
		return board != null && board.side() > 0 && board.side() <= MAX_MINI_BOARD;
	}

	/** The board the card draws, or null. */
	DiscoveryResponse.Board miniBoard()
	{
		return drawn(board) ? board : null;
	}

	/** One line per Team the player is on: "Red: 2nd of 3, 340 pts". */
	private static List<String> bingoStanding(DiscoveryResponse.Board board)
	{
		List<String> lines = new ArrayList<>();
		for (DiscoveryResponse.BoardTeam team : board.mine())
		{
			lines.add(team.getName() + ": " + bingoPlace(team));
		}
		return lines;
	}

	/** The best of the player's Teams; Teams come in standings order. */
	private static String bingoRank(DiscoveryResponse.Board board)
	{
		List<DiscoveryResponse.BoardTeam> mine = board.mine();
		return mine.isEmpty() ? "" : ordinal(mine.get(0).getRank()) + "/" + mine.get(0).getOf();
	}

	/** A bingo Team's place: "2nd of 3, 340 pts". */
	static String bingoPlace(DiscoveryResponse.BoardTeam team)
	{
		return String.format(Locale.ENGLISH, "%s of %d, %,d pts", ordinal(team.getRank()), team.getOf(), team.getPoints());
	}

	private static List<String> notes(Queued queued)
	{
		List<String> notes = new ArrayList<>();
		if (queued.getWaiting() > 0)
		{
			notes.add(queued.getWaiting() + " waiting to send");
		}
		if (queued.getPushedOut() > 0)
		{
			notes.add(queued.getPushedOut() + " taken out of the full send queue: upload "
				+ (queued.getPushedOut() == 1 ? "it" : "them") + " on the event page");
		}
		return notes;
	}

	private static CardState state(DiscoveryResponse.DiscoveredEvent event, boolean left)
	{
		String phase = event.getPhase();
		if (left)
		{
			return CardState.LEFT;
		}
		if (DiscoveryResponse.REMOVED.equals(event.getEntry()))
		{
			return CardState.NOT_ON_ROSTER;
		}
		if (DiscoveryResponse.FINALIZED.equals(phase))
		{
			return CardState.FINAL;
		}
		// Still worth attention after end: a mismatch settled during review lets the progress count,
		// and needs-evidence uploads stay open until Finalize
		if (DiscoveryResponse.HELD.equals(event.getEntry()) || event.getNeedsEvidence() > 0)
		{
			return CardState.ATTENTION;
		}
		if (DiscoveryResponse.ENDED.equals(phase))
		{
			return CardState.ENDED;
		}
		if (DiscoveryResponse.PUBLISHED.equals(phase) && event.getVote() != null)
		{
			return CardState.VOTING;
		}
		if (DiscoveryResponse.PUBLISHED.equals(phase))
		{
			return CardState.NOT_SCHEDULED;
		}
		return CardState.TRACKING;
	}

	private static String detail(DiscoveryResponse.DiscoveredEvent event, CardState state, ZoneId zone)
	{
		switch (state)
		{
			case LEFT:
				return "Left on this install, nothing is sent";
			case NOT_ON_ROSTER:
				return "No longer on the roster";
			case FINAL:
				return "Final standing";
			case ENDED:
				return "Ended, results provisional";
			case ATTENTION:
				if (DiscoveryResponse.HELD.equals(event.getEntry()))
				{
					return "On hold while Friendscape checks this RSN";
				}
				int items = event.getNeedsEvidence();
				return items == 1 ? "1 item needs a screenshot" : items + " items need a screenshot";
			case NOT_SCHEDULED:
				return "Not scheduled yet";
			case VOTING:
				Instant closesAt = DiscoveryResponse.parse(event, event.getVote().getClosesAt());
				return closesAt == null ? "Voting" : "Voting, closes " + STARTS.format(closesAt.atZone(zone));
			default:
				Instant startsAt = DiscoveryResponse.parse(event, event.getStartsAt());
				if (DiscoveryResponse.SCHEDULED.equals(event.getPhase()) && startsAt != null)
				{
					return "Starts " + STARTS.format(startsAt.atZone(zone));
				}
				return "Tracking";
		}
	}

	/** Standings mean something once the Event has started. */
	private static boolean hasStanding(DiscoveryResponse.DiscoveredEvent event)
	{
		return event.getStanding() != null && event.getStanding().getTeams() != null && started(event);
	}

	private static boolean started(DiscoveryResponse.DiscoveredEvent event)
	{
		String phase = event.getPhase();
		return DiscoveryResponse.LIVE.equals(phase) || DiscoveryResponse.ENDED.equals(phase)
			|| DiscoveryResponse.FINALIZED.equals(phase);
	}

	private static List<String> standing(DiscoveryResponse.DiscoveredEvent event)
	{
		String unit = "botw".equals(event.getFormat()) ? "kc" : "xp";
		List<String> lines = new ArrayList<>();
		boolean onRealTeam = false;
		for (DiscoveryResponse.TeamStanding team : event.getStanding().getTeams())
		{
			String place = ordinal(team.getRank()) + " of " + team.getOf() + ", " + gain(team.getGain(), unit);
			lines.add(team.isSolo() ? place : team.getName() + ": " + place);
			onRealTeam |= !team.isSolo();
		}
		if (onRealTeam)
		{
			lines.add(gain(event.getStanding().getGain(), unit) + " since start");
		}
		return lines;
	}

	private static String rank(DiscoveryResponse.Standing standing)
	{
		if (standing.getTeams().isEmpty())
		{
			return "";
		}
		DiscoveryResponse.TeamStanding best = standing.getTeams().get(0);
		return ordinal(best.getRank()) + "/" + best.getOf();
	}

	private static String gain(long gain, String unit)
	{
		return String.format(Locale.ENGLISH, "+%,d %s", gain, unit);
	}

	/** 1st, 2nd, 3rd, 4th, ..., 11th, 12th, 13th, 21st. */
	static String ordinal(int n)
	{
		int lastTwo = n % 100;
		if (lastTwo >= 11 && lastTwo <= 13)
		{
			return n + "th";
		}
		switch (n % 10)
		{
			case 1:
				return n + "st";
			case 2:
				return n + "nd";
			case 3:
				return n + "rd";
			default:
				return n + "th";
		}
	}
}

package com.friendscape;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * The only way out of the client. Every call is refused unless {@code permitted} says yes at
 * enqueue time, runs on OkHttp's dispatcher threads (never the client thread), and has its result
 * dropped if permission was withdrawn or the call cancelled while it was in flight.
 */
@Slf4j
class FriendscapeApi
{
	private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");
	private static final MediaType PNG = MediaType.get("image/png");

	private final OkHttpClient http;
	private final Gson gson;
	private final HttpUrl base;
	private final BooleanSupplier permitted;
	private final Set<Call> inFlight = ConcurrentHashMap.newKeySet();

	FriendscapeApi(OkHttpClient http, Gson gson, HttpUrl base, BooleanSupplier permitted)
	{
		this.http = http;
		this.gson = gson;
		this.base = base;
		this.permitted = permitted;
	}

	/**
	 * Reports whether the server answered its health route. Called back on an OkHttp thread, and
	 * not at all if the call was refused or cancelled.
	 */
	void checkHealth(Consumer<Boolean> onResult)
	{
		Request request = new Request.Builder().url(base.resolve("health")).get().build();
		enqueue(request, response -> onResult.accept(response.isSuccessful()), error -> onResult.accept(false));
	}

	/**
	 * Asks which Events roster the character, with each one's phase, Roster entry state and
	 * standing. {@code onReachable} hears whether the server answered at all: a refusal (4xx) is an
	 * answer, a server error or failed connection is not; {@code onResult} hears only a successful
	 * answer. Both come back on an OkHttp thread, and neither for a call refused here or cancelled.
	 */
	void discover(String rsn, long accountHash, Consumer<DiscoveryResponse> onResult, Consumer<Boolean> onReachable)
	{
		Request request = new Request.Builder()
			.url(base.resolve("v1/plugin/discovery"))
			.post(RequestBody.create(JSON, gson.toJson(identity(rsn, accountHash))))
			.build();
		enqueue(request, response ->
		{
			onReachable.accept(response.code() < 500);
			DiscoveryResponse parsed = parse(response, DiscoveryResponse.class);
			if (parsed != null)
			{
				onResult.accept(parsed);
			}
		}, error -> onReachable.accept(false));
	}

	/** The website's page for an Event: {@code /e/<number>} on the API's host. */
	static String eventPage(HttpUrl base, int number)
	{
		return base.newBuilder().encodedPath("/e/").addPathSegment(Integer.toString(number)).build().toString();
	}

	/** The website's upload page for an Event, for needs-evidence and manual uploads. */
	static String uploadPage(HttpUrl base, int number)
	{
		return base.newBuilder().encodedPath("/e/").addPathSegment(Integer.toString(number)).addPathSegment("upload").build().toString();
	}

	/** A Team's board page: {@code /e/<number>/t/<team>}. */
	static String teamPage(HttpUrl base, int number, int teamNumber)
	{
		return teamPageUrl(base, number, teamNumber).build().toString();
	}

	/** One Tile's detail on a Team's board page: {@code /e/<number>/t/<team>?tile=<n>}. */
	static String tilePage(HttpUrl base, int number, int teamNumber, int tile)
	{
		return teamPageUrl(base, number, teamNumber).addQueryParameter("tile", Integer.toString(tile)).build().toString();
	}

	private static HttpUrl.Builder teamPageUrl(HttpUrl base, int number, int teamNumber)
	{
		return base.newBuilder().encodedPath("/e/").addPathSegment(Integer.toString(number)).addPathSegment("t")
			.addPathSegment(Integer.toString(teamNumber)).query(null);
	}

	private static Map<String, Object> identity(String rsn, long accountHash)
	{
		Map<String, Object> body = new LinkedHashMap<>();
		body.put("rsn", rsn);
		// A Java long does not fit a JSON number, so the hash travels as text
		body.put("accountHash", Long.toString(accountHash));
		return body;
	}

	/**
	 * Sends absolute skill XP by skill slug and lifetime KC by the name chat uses for it (the server
	 * maps names to activities), either of which may be empty. Marked as the start or end Reading
	 * for {@code moments}.
	 * Readings are never queued or retried: a failed send is dropped, since the next Reading carries
	 * a total that covers it. {@code muted} holds the numbers of the Events left on this install. The server's
	 * answer comes back on an OkHttp thread; nothing comes back for a failed or refused send.
	 */
	void sendReadings(String rsn, long accountHash, Map<String, Long> xp, Map<String, Long> kcChat,
		Set<Moment> moments, Set<Integer> muted, Consumer<ReadingsResponse> onResult)
	{
		Map<String, Object> body = identity(rsn, accountHash);
		if (!xp.isEmpty())
		{
			body.put("xp", xp);
		}
		if (!kcChat.isEmpty())
		{
			body.put("kcChat", kcChat);
		}
		if (moments.contains(Moment.START))
		{
			body.put("atStart", true);
		}
		if (moments.contains(Moment.END))
		{
			body.put("atEnd", true);
		}
		if (!muted.isEmpty())
		{
			// Named on each Reading only: the server captures nothing for these and stores no Leave
			body.put("muted", muted);
		}
		Request request = new Request.Builder()
			.url(base.resolve("v1/plugin/readings"))
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();
		enqueue(request, response ->
		{
			ReadingsResponse parsed = parse(response, ReadingsResponse.class);
			if (parsed != null)
			{
				onResult.accept(parsed);
			}
		}, error -> log.debug("Reading dropped: {}", error.getMessage()));
	}

	static final String REPORT_FAILED = "Could not report to Friendscape. Try again later.";
	static final String NOTHING_TO_REPORT = "Nothing held to report: it may be settled already.";
	static final String TOO_MANY_REPORTS = "Too many reports from here. Try again in an hour.";

	/** The server's answer to a report: {@code {"status", "message"}}. */
	@Value
	static class ReportAnswer
	{
		String status;
		String message;
	}

	/**
	 * "Report to Friendscape" on a held card (SPEC 10.3): asks the admin to look at the identity
	 * mismatch over {@code rsn}, from the card of Event {@code number}. {@code onMessage} hears what to tell
	 * the player, on an OkHttp thread; nothing for a call refused here or cancelled.
	 */
	void report(String rsn, long accountHash, int number, Consumer<String> onMessage)
	{
		Map<String, Object> body = identity(rsn, accountHash);
		body.put("number", number);
		Request request = new Request.Builder()
			.url(base.resolve("v1/plugin/report"))
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();
		enqueue(request, response ->
		{
			if (response.code() == 404)
			{
				onMessage.accept(NOTHING_TO_REPORT);
				return;
			}
			if (response.code() == 429)
			{
				onMessage.accept(TOO_MANY_REPORTS);
				return;
			}
			ReportAnswer answer = parse(response, ReportAnswer.class);
			onMessage.accept(answer == null || answer.getMessage() == null ? REPORT_FAILED : answer.getMessage());
		}, error -> onMessage.accept(REPORT_FAILED));
	}

	static final String VOTE_FAILED = "Could not vote. Try again later.";

	/** The server's answer to a vote: the Vote as it now stands. */
	@Value
	static class VoteAnswer
	{
		DiscoveryResponse.Vote vote;
	}

	/** The body of a refusal: {@code {"error"}}. */
	@Value
	static class ErrorAnswer
	{
		String error;
	}

	/**
	 * Votes from the card of Event {@code number} for the Candidate {@code candidate} (its Ballot
	 * place, SPEC 4.9). {@code onVote} hears the Vote as it now stands; {@code onRefused} what to tell
	 * the player instead. Either comes back on an OkHttp thread; nothing for a call refused here or
	 * cancelled.
	 */
	void vote(String rsn, long accountHash, int number, int candidate, Consumer<DiscoveryResponse.Vote> onVote,
		Consumer<String> onRefused)
	{
		Map<String, Object> body = identity(rsn, accountHash);
		body.put("number", number);
		body.put("candidate", candidate);
		Request request = new Request.Builder()
			.url(base.resolve("v1/plugin/vote"))
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();
		enqueue(request, response ->
		{
			if (response.code() >= 400 && response.code() < 500)
			{
				String error = errorMessage(response);
				onRefused.accept(error == null ? VOTE_FAILED : error);
				return;
			}
			VoteAnswer answer = parse(response, VoteAnswer.class);
			if (answer == null || answer.getVote() == null)
			{
				onRefused.accept(VOTE_FAILED);
				return;
			}
			onVote.accept(answer.getVote());
		}, error -> onRefused.accept(VOTE_FAILED));
	}

	/** A refusal's {@code error}, worded for the player by the server; null when it has none. */
	private String errorMessage(Response response)
	{
		ResponseBody body = response.body();
		if (body == null)
		{
			return null;
		}
		try
		{
			ErrorAnswer answer = gson.fromJson(body.charStream(), ErrorAnswer.class);
			return answer == null ? null : answer.getError();
		}
		catch (JsonParseException e)
		{
			log.debug("Unreadable refusal from {}", response.request().url(), e);
			return null;
		}
	}

	/** How a Submission send ended; called back on an OkHttp thread, not at all if refused here or cancelled. */
	interface SubmissionCallback
	{
		/** The server took it: any outcome settles it. */
		void answered(SubmissionResponse response);

		/** The server refused it for good (a 4xx other than 408 and 429): resending would not help. */
		void refused(int code);

		/** No answer, a timeout, rate limit, server error or unreadable body: worth a retry. */
		void failed();
	}

	/**
	 * Sends an item, clog or pet Submission (SPEC 5.4) as multipart: the queued Submission's fields and
	 * the screenshot, which is left out when capture failed. {@code muted} holds the numbers of the Events
	 * left on this install. False when refused here, as sending is off: the callback never fires.
	 */
	boolean sendSubmission(QueuedSubmission submission, byte[] png, Set<Integer> muted, SubmissionCallback callback)
	{
		MultipartBody.Builder body = new MultipartBody.Builder()
			.setType(MultipartBody.FORM)
			.addFormDataPart("rsn", submission.getRsn())
			.addFormDataPart("accountHash", submission.getAccountHash())
			.addFormDataPart("idempotencyId", submission.getId())
			.addFormDataPart("capturedAt", submission.getCapturedAt())
			.addFormDataPart("kind", submission.getKind())
			.addFormDataPart("quantity", Integer.toString(submission.getQuantity()));
		if (submission.getItemId() != null)
		{
			body.addFormDataPart("itemId", Integer.toString(submission.getItemId()));
		}
		if (!muted.isEmpty())
		{
			body.addFormDataPart("muted", gson.toJson(muted));
		}
		if (png != null)
		{
			body.addFormDataPart("screenshot", "screenshot.png", RequestBody.create(PNG, png));
		}
		Request request = new Request.Builder()
			.url(base.resolve("v1/plugin/submissions"))
			.post(body.build())
			.build();
		return enqueue(request, response ->
		{
			int code = response.code();
			// A timeout or rate limit is passing; any other 4xx would fail again
			if (code >= 400 && code < 500 && code != 408 && code != 429)
			{
				callback.refused(code);
				return;
			}
			SubmissionResponse parsed = parse(response, SubmissionResponse.class);
			if (parsed == null)
			{
				callback.failed();
			}
			else
			{
				callback.answered(parsed);
			}
		}, error -> callback.failed());
	}

	/** The JSON body of a successful response, or null (logged) for an error status or bad body. */
	private <T> T parse(Response response, Class<T> type)
	{
		ResponseBody body = response.body();
		if (!response.isSuccessful() || body == null)
		{
			log.debug("{} {} answered {}", response.request().method(), response.request().url(), response.code());
			return null;
		}
		try
		{
			return gson.fromJson(body.charStream(), type);
		}
		catch (JsonParseException e)
		{
			log.warn("Unreadable answer from {}", response.request().url(), e);
			return null;
		}
	}

	/** Cancels every in-flight call; their callbacks never fire. */
	void cancelAll()
	{
		// Remove one by one: clear() could drop a call enqueued mid-loop without cancelling it
		for (Call call : inFlight)
		{
			call.cancel();
			inFlight.remove(call);
		}
	}

	/** False when refused here: sending is off, logged out or the world is not tracked. */
	private boolean enqueue(Request request, Consumer<Response> onResponse, Consumer<IOException> onFailure)
	{
		if (!permitted.getAsBoolean())
		{
			log.debug("Refused {} {}: sending is off or this world is not tracked", request.method(), request.url());
			return false;
		}

		Call call = http.newCall(request);
		inFlight.add(call);
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				if (claimResult(call))
				{
					log.debug("{} {} failed", request.method(), request.url(), e);
					onFailure.accept(e);
				}
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (response)
				{
					if (claimResult(call))
					{
						onResponse.accept(response);
					}
				}
			}
		});
		return true;
	}

	/** Removes the call from the in-flight set; true if its result should still be delivered. */
	private boolean claimResult(Call call)
	{
		inFlight.remove(call);
		return !call.isCanceled() && permitted.getAsBoolean();
	}
}

