package com.friendscape;

import java.time.Duration;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;

/** The server's answer to a Reading: what it did for each Event the character is rostered in. */
@Slf4j
@Value
class ReadingsResponse
{
	/** Sent this long after an Event's start or end, so the server's clock is past it too. */
	static final Duration MOMENT_MARGIN = Duration.ofSeconds(2);
	/** Retry delay when the server has not reached a start or end this clock is past. */
	static final Duration MOMENT_RETRY = Duration.ofSeconds(10);

	static final String COUNTED = "counted";
	static final String NOT_STARTED = "not_started";
	static final String ENDED = "ended";
	static final String HELD = "held";
	static final String NOT_ON_ROSTER = "not_on_roster";

	String rsn;
	/** Empty when the character is on no roster: the Readings were dropped. */
	List<EventReading> events;

	@Value
	static class EventReading
	{
		int number;
		/** {@code counted}, {@code not_started}, {@code ended}, {@code held} or {@code not_on_roster}. */
		String status;
		String startsAt;
		String endsAt;
	}

	/** This answer less the Events the player left: no start or end Reading is sent for them. */
	ReadingsResponse without(Set<Integer> left)
	{
		if (events == null || left.isEmpty())
		{
			return this;
		}
		List<EventReading> kept = new ArrayList<>();
		for (EventReading event : events)
		{
			if (!left.contains(event.getNumber()))
			{
				kept.add(event);
			}
		}
		return new ReadingsResponse(rsn, kept);
	}

	/** The status this answer gives each Event, by Event number. */
	Map<Integer, String> statuses()
	{
		Map<Integer, String> statuses = new HashMap<>();
		if (events != null)
		{
			for (EventReading event : events)
			{
				statuses.put(event.getNumber(), event.getStatus());
			}
		}
		return statuses;
	}

	/**
	 * When to send the next start or end Reading (every skill), or null when no Event has one to
	 * come: the start of an Event not started yet, or the end of one counting. Readings before start
	 * are ignored, so the start Reading is the first to count; the end Reading is the last.
	 */
	Instant nextMomentReading(Instant now)
	{
		if (events == null)
		{
			return null;
		}
		Instant next = null;
		for (EventReading event : events)
		{
			Instant moment = moment(event);
			if (moment == null)
			{
				continue;
			}
			// Already past here but not on the server: its clock is behind, so ask again shortly
			Instant at = moment.isAfter(now) ? moment.plus(MOMENT_MARGIN) : now.plus(MOMENT_RETRY);
			if (next == null || at.isBefore(next))
			{
				next = at;
			}
		}
		return next;
	}

	/** The moments this clock has passed, as of this answer: what a Reading sent now marks. */
	Set<Moment> momentsDue(Instant now)
	{
		Set<Moment> due = EnumSet.noneOf(Moment.class);
		if (events == null)
		{
			return due;
		}
		for (EventReading event : events)
		{
			Instant moment = moment(event);
			if (moment != null && !moment.isAfter(now))
			{
				due.add(NOT_STARTED.equals(event.getStatus()) ? Moment.START : Moment.END);
			}
		}
		return due;
	}

	/** The Event's next moment: its start while not started, its end while counting, else null. */
	private static Instant moment(EventReading event)
	{
		String at;
		if (NOT_STARTED.equals(event.getStatus()))
		{
			at = event.getStartsAt();
		}
		else if (COUNTED.equals(event.getStatus()))
		{
			at = event.getEndsAt();
		}
		else
		{
			return null;
		}
		if (at == null)
		{
			return null;
		}
		try
		{
			return Instant.parse(at);
		}
		catch (DateTimeParseException e)
		{
			log.warn("Ignoring Event {} with an unreadable moment {}", event.getNumber(), at);
			return null;
		}
	}
}

package com.friendscape;

import java.util.Arrays;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * A stored set of Event numbers, such as those left on this install: comma-separated. Anything
 * that is not an Event number, such as a slug stored before Events were numbered, is dropped.
 */
final class StoredEventNumbers
{
	/** Six digits, never a leading zero: 100000 to 999999. */
	private static final Pattern EVENT_NUMBER = Pattern.compile("[1-9][0-9]{5}");

	private StoredEventNumbers()
	{
	}

	/** True for a number in 100000 to 999999. */
	static boolean isEventNumber(Integer number)
	{
		return number != null && number >= 100000 && number <= 999999;
	}

	static Set<Integer> parse(String stored)
	{
		if (stored == null || stored.isEmpty())
		{
			return Set.of();
		}
		return Arrays.stream(stored.split(","))
			.filter(s -> EVENT_NUMBER.matcher(s).matches())
			.map(Integer::valueOf)
			.collect(Collectors.toUnmodifiableSet());
	}

	/** The stored set less every number not in {@code kept}, formatted. */
	static String prune(String stored, Set<Integer> kept)
	{
		Set<Integer> pruned = new TreeSet<>(parse(stored));
		pruned.retainAll(kept);
		return format(pruned);
	}

	static String format(Set<Integer> numbers)
	{
		return new TreeSet<>(numbers).stream().map(String::valueOf).collect(Collectors.joining(","));
	}
}

package com.friendscape;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.IntFunction;
import java.util.function.IntUnaryOperator;
import lombok.Value;
import net.runelite.client.game.ItemStack;
import net.runelite.http.api.loottracker.LootRecordType;

/**
 * Turns loot and chat lines into item, clog and pet Submissions (SPEC 10.2), keeping only those
 * some open Tile watches. Called on the client thread only.
 */
class SubmissionDetector
{
	/**
	 * How long a pet line waits for the line that names the pet. Both come in the same tick in
	 * practice; the slack covers a slow chat.
	 */
	static final int PET_NAME_TICKS = 3;

	/** The server's Submission kinds; pets are items. */
	enum Kind
	{
		ITEM,
		CLOG_SLOT;

		/** As the server spells it: {@code item}, {@code clog_slot}. */
		String wire()
		{
			return name().toLowerCase(Locale.ROOT);
		}
	}

	@Value
	static class Drop
	{
		Kind kind;
		/** Canonical; null on a clog slot whose name no watched item pins. */
		Integer itemId;
		/** For chat lines: the item's name. */
		String name;
		int quantity;
		/** The Events whose open Tiles watch it: the queue keeps it while any of them may count it. */
		Set<Integer> events;
	}

	private final IntUnaryOperator canonicalize;
	private final IntFunction<String> itemName;
	private WatchList watch = WatchList.EMPTY;
	/** Ticks left for a pet line's name to arrive; 0 when no pet is waiting for one. */
	private int petTicksLeft;
	private int tick;
	/** The tick each item id last came in loot: its own untradeable line is not a pet's name. */
	private final Map<Integer, Integer> lootedAt = new HashMap<>();

	/**
	 * @param canonicalize {@code ItemManager.canonicalize}: notes and placeholders to the item
	 * @param itemName an item's name, for the chat line when it counts
	 */
	SubmissionDetector(IntUnaryOperator canonicalize, IntFunction<String> itemName)
	{
		this.canonicalize = canonicalize;
		this.itemName = itemName;
	}

	void setWatch(WatchList watch)
	{
		this.watch = watch;
	}

	/**
	 * Whether {@code LootReceived} of this type is a drop to check: raids, chests, clues, minigames
	 * and pickpockets. NPC kills come through {@code ServerNpcLoot} instead, and loot from another
	 * player is not the player's own drop.
	 */
	static boolean countsLoot(LootRecordType type)
	{
		return type == LootRecordType.EVENT || type == LootRecordType.PICKPOCKET;
	}

	/** One watched Drop per item id in the loot, stacks of the same item added up. */
	List<Drop> loot(Collection<ItemStack> items)
	{
		Map<Integer, Integer> quantities = new LinkedHashMap<>();
		for (ItemStack stack : items)
		{
			quantities.merge(canonicalize.applyAsInt(stack.getId()), stack.getQuantity(), Integer::sum);
		}
		quantities.keySet().forEach(id -> lootedAt.put(id, tick));
		List<Drop> drops = new ArrayList<>();
		quantities.forEach((id, quantity) ->
		{
			Set<Integer> events = watch.eventsFor(id);
			if (!events.isEmpty())
			{
				drops.add(new Drop(Kind.ITEM, id, itemName.apply(id), quantity, events));
			}
		});
		return drops;
	}

	/** The watched Drops a game message reports: a named pet, a new clog slot, or none. */
	List<Drop> chat(String message)
	{
		DropMessages.Line line = DropMessages.parse(message);
		if (line == null)
		{
			return List.of();
		}
		if (line.getKind() == DropMessages.Kind.PET)
		{
			petTicksLeft = PET_NAME_TICKS;
			return List.of();
		}
		List<Drop> drops = new ArrayList<>();
		Integer id = watch.idForName(line.getName());
		if (petTicksLeft > 0 && id != null && !lootedLately(id))
		{
			// The pet line's name: the untradeable drop line, or the clog line when that comes first
			petTicksLeft = 0;
			drops.add(new Drop(Kind.ITEM, id, line.getName(), 1, watch.eventsFor(id)));
		}
		if (line.getKind() == DropMessages.Kind.CLOG_SLOT && !watch.clogSlotEvents().isEmpty())
		{
			drops.add(new Drop(Kind.CLOG_SLOT, id, line.getName(), 1, watch.clogSlotEvents()));
		}
		return drops;
	}

	void tick()
	{
		tick++;
		if (petTicksLeft > 0)
		{
			petTicksLeft--;
		}
		lootedAt.values().removeIf(at -> tick - at > PET_NAME_TICKS);
	}

	private boolean lootedLately(int id)
	{
		Integer at = lootedAt.get(id);
		return at != null && tick - at <= PET_NAME_TICKS;
	}
}

package com.friendscape;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.time.Duration;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import lombok.extern.slf4j.Slf4j;

/**
 * Item, clog and pet Submissions waiting to send (SPEC 10.5), on disk so they survive restarts:
 * {@code <id>.json} and its screenshot {@code <id>.png}. Every Submission goes through here and
 * leaves once the server answers, so a crash mid-send loses nothing. The JSON is written last,
 * so an submission exists only once complete. Thread-safe; does file IO, so never call it on the
 * client thread.
 */
@Slf4j
class SubmissionQueue
{
	static final int CAP = 20;
	static final Duration FIRST_RETRY = Duration.ofSeconds(30);
	private static final Duration LAST_RETRY = Duration.ofMinutes(15);
	private static final String JSON = ".json";
	private static final String PNG = ".png";

	private final File dir;
	private final Gson gson;
	/** By id, oldest capture first. */
	private final Map<String, QueuedSubmission> submissions = new LinkedHashMap<>();
	private final Map<String, Integer> failures = new HashMap<>();
	private final Map<String, Instant> retryAt = new HashMap<>();
	private final Set<String> inFlight = new HashSet<>();

	private SubmissionQueue(File dir, Gson gson)
	{
		this.dir = dir;
		this.gson = gson;
	}

	/** Loads what a previous run left, deleting orphaned and unreadable files. */
	static SubmissionQueue open(File dir, Gson gson) throws IOException
	{
		Files.createDirectories(dir.toPath());
		SubmissionQueue queue = new SubmissionQueue(dir, gson);
		queue.load();
		return queue;
	}

	private void load() throws IOException
	{
		File[] files = dir.listFiles();
		if (files == null)
		{
			throw new IOException("Cannot list " + dir);
		}
		List<QueuedSubmission> loaded = new ArrayList<>();
		Set<String> kept = new HashSet<>();
		for (File file : files)
		{
			if (file.getName().endsWith(JSON))
			{
				QueuedSubmission submission = read(file);
				if (submission != null)
				{
					loaded.add(submission);
					kept.add(file.getName());
					kept.add(submission.getId() + PNG);
				}
			}
		}
		for (File file : files)
		{
			if (!kept.contains(file.getName()))
			{
				log.debug("Removing orphaned queue file {}", file.getName());
				Files.deleteIfExists(file.toPath());
			}
		}
		loaded.sort(Comparator.comparing(SubmissionQueue::capturedAt));
		for (QueuedSubmission submission : loaded)
		{
			submissions.put(submission.getId(), submission);
		}
	}

	private QueuedSubmission read(File file)
	{
		try
		{
			QueuedSubmission submission = gson.fromJson(new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8), QueuedSubmission.class);
			if (submission != null && file.getName().equals(submission.getId() + JSON) && capturedAt(submission) != Instant.MIN
				&& hasEventNumbers(submission))
			{
				return submission;
			}
		}
		catch (IOException | JsonParseException e)
		{
			// Also an entry stored with Event slugs, before Events were numbered: load() deletes it
			log.warn("Unreadable queued Submission {}", file.getName(), e);
		}
		return null;
	}

	/** Every Event it names is an Event number; false for one stored before Events were numbered. */
	private static boolean hasEventNumbers(QueuedSubmission submission)
	{
		return submission.getEvents() != null && submission.getEvents().stream().allMatch(StoredEventNumbers::isEventNumber);
	}

	/**
	 * Keeps a Submission until the server answers; {@code png} is null when capture failed. Past
	 * the cap the oldest go to make room, and are returned for a notice to upload them by hand.
	 */
	synchronized List<QueuedSubmission> add(QueuedSubmission submission, byte[] png) throws IOException
	{
		if (png != null)
		{
			write(new File(dir, submission.getId() + PNG), png);
		}
		write(new File(dir, submission.getId() + JSON), gson.toJson(submission).getBytes(StandardCharsets.UTF_8));
		submissions.put(submission.getId(), submission);
		List<QueuedSubmission> dropped = new ArrayList<>();
		while (submissions.size() > CAP)
		{
			QueuedSubmission oldest = submissions.values().stream().min(Comparator.comparing(SubmissionQueue::capturedAt)).orElseThrow();
			remove(oldest.getId());
			dropped.add(oldest);
		}
		return dropped;
	}

	/** Entries of this account due a send now, oldest first; none already in flight. */
	synchronized List<QueuedSubmission> due(long accountHash, Instant now)
	{
		String hash = Long.toString(accountHash);
		List<QueuedSubmission> due = new ArrayList<>();
		for (QueuedSubmission submission : submissions.values())
		{
			Instant at = retryAt.get(submission.getId());
			if (hash.equals(submission.getAccountHash()) && !inFlight.contains(submission.getId()) && (at == null || !now.isBefore(at)))
			{
				due.add(submission);
			}
		}
		return due;
	}

	/** The screenshot to send with an submission, or null without one. */
	synchronized byte[] screenshot(String id) throws IOException
	{
		File png = new File(dir, id + PNG);
		return png.exists() ? Files.readAllBytes(png.toPath()) : null;
	}

	/**
	 * Takes this account's due Submissions to send, marking them in flight in the same step, so
	 * two flushes never send one twice.
	 */
	synchronized List<QueuedSubmission> takeDue(long accountHash, Instant now)
	{
		List<QueuedSubmission> due = due(accountHash, now);
		due.forEach(submission -> inFlight.add(submission.getId()));
		return due;
	}

	/** A send that never left (sending turned off meanwhile): due again, without backoff. */
	synchronized void release(String id)
	{
		inFlight.remove(id);
	}

	/** No answer: retried after a backoff that doubles each time, up to {@link #LAST_RETRY}. */
	synchronized void failed(String id, Instant now)
	{
		inFlight.remove(id);
		if (!submissions.containsKey(id))
		{
			return;
		}
		int failed = failures.merge(id, 1, Integer::sum);
		Duration wait = FIRST_RETRY.multipliedBy(1L << Math.min(failed - 1, 10));
		retryAt.put(id, now.plus(wait.compareTo(LAST_RETRY) > 0 ? LAST_RETRY : wait));
	}

	/** Answered, pruned or pushed out: the submission and its screenshot go. */
	synchronized void remove(String id)
	{
		submissions.remove(id);
		failures.remove(id);
		retryAt.remove(id);
		inFlight.remove(id);
		try
		{
			Files.deleteIfExists(new File(dir, id + JSON).toPath());
			Files.deleteIfExists(new File(dir, id + PNG).toPath());
		}
		catch (IOException e)
		{
			// Left behind, the next start removes it as an orphan
			log.warn("Could not delete queued Submission {}", id, e);
		}
	}

	/**
	 * Drops this account's submissions no Event can count any more: each of its Events gone from
	 * discovery (card removed) or past {@code keepUntil} (its end plus Grace window; null while it
	 * has no end). Another account's submissions wait for that account's own discovery.
	 */
	synchronized List<QueuedSubmission> prune(long accountHash, Map<Integer, Instant> keepUntil, Instant now)
	{
		String hash = Long.toString(accountHash);
		List<QueuedSubmission> pruned = new ArrayList<>();
		for (QueuedSubmission submission : new ArrayList<>(submissions.values()))
		{
			if (!hash.equals(submission.getAccountHash()))
			{
				continue;
			}
			boolean wanted = false;
			for (Integer number : submission.getEvents())
			{
				Instant until = keepUntil.get(number);
				wanted |= keepUntil.containsKey(number) && (until == null || now.isBefore(until));
			}
			if (!wanted)
			{
				remove(submission.getId());
				pruned.add(submission);
			}
		}
		return pruned;
	}

	/** How many submissions wait per Event number, by account hash: the cards' "waiting to send". */
	synchronized Map<String, Map<Integer, Integer>> waiting()
	{
		Map<String, Map<Integer, Integer>> waiting = new HashMap<>();
		for (QueuedSubmission submission : submissions.values())
		{
			Map<Integer, Integer> byEvent = waiting.computeIfAbsent(submission.getAccountHash(), hash -> new TreeMap<>());
			submission.getEvents().forEach(number -> byEvent.merge(number, 1, Integer::sum));
		}
		return waiting;
	}

	/** Calls cut off before they answered (logout, hop, sending off): due again at once. */
	synchronized void clearInFlight()
	{
		inFlight.clear();
	}

	private static void write(File file, byte[] bytes) throws IOException
	{
		File temp = new File(file.getParentFile(), file.getName() + ".tmp");
		Files.write(temp.toPath(), bytes);
		Files.move(temp.toPath(), file.toPath(), StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
	}

	/** Its capture time, or {@link Instant#MIN} when unreadable. */
	private static Instant capturedAt(QueuedSubmission submission)
	{
		if (submission.getCapturedAt() == null)
		{
			return Instant.MIN;
		}
		try
		{
			return Instant.parse(submission.getCapturedAt());
		}
		catch (DateTimeParseException e)
		{
			// Hand-edited or from a broken write: load() deletes it
			return Instant.MIN;
		}
	}
}

package com.friendscape;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import lombok.Value;

/**
 * The server's answer to an item, clog or pet Submission: one outcome per Event that rosters the
 * player. Any answer settles the Submission, so the queue drops it.
 */
@Value
class SubmissionResponse
{
	static final String COUNTED = "counted";
	static final String PENDING = "pending";
	static final String REJECTED = "rejected";

	String rsn;
	/** A resend of an id already taken: the outcomes are the stored ones. */
	boolean duplicate;
	List<EventOutcome> events;

	@Value
	static class EventOutcome
	{
		int number;
		/**
		 * {@code counted}, {@code needs_evidence}, {@code pending}, {@code held}, {@code rejected},
		 * or a refusal that stored nothing: {@code not_started}, {@code ended}, {@code not_on_roster}.
		 */
		String status;
		/** The public reason for a rejection. */
		String reason;
	}

	/**
	 * The chat lines for this answer (SPEC 10.4): one for counting, naming how many Events when
	 * several count it, one per review and one per rejection with its reason. Held shows through
	 * discovery, needs evidence when the screenshot failed.
	 *
	 * @param eventNames Event names by Event number, from discovery; "Event <number>" stands in for an unknown one
	 */
	List<ProblemNotices.Notice> notices(QueuedSubmission submission, Map<Integer, String> eventNames, boolean chatOnCounted)
	{
		String what = submission.isClogSlot()
			? "New collection log slot (" + submission.getName() + ")" : submission.getName();
		List<String> counted = new ArrayList<>();
		List<ProblemNotices.Notice> notices = new ArrayList<>();
		for (EventOutcome outcome : events == null ? List.<EventOutcome>of() : events)
		{
			String event = eventNames.getOrDefault(outcome.getNumber(), "Event " + outcome.getNumber());
			switch (outcome.getStatus())
			{
				case COUNTED:
					counted.add(event);
					break;
				case PENDING:
					notices.add(new ProblemNotices.Notice(what + " is waiting for review in " + event + ".", false));
					break;
				case REJECTED:
					notices.add(new ProblemNotices.Notice(what + " was rejected in " + event + ": " + outcome.getReason(), true));
					break;
				default:
					break;
			}
		}
		if (chatOnCounted && !counted.isEmpty())
		{
			String where = counted.size() == 1 ? counted.get(0) : counted.size() + " Events";
			notices.add(0, new ProblemNotices.Notice(what + " counted for " + where + ".", false));
		}
		return notices;
	}
}

package com.friendscape;

import java.io.IOException;
import java.time.Instant;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;

/**
 * Sends item, clog and pet Submissions through the disk queue (SPEC 10.5) and tells the player
 * how each went (SPEC 10.4). Every call does file IO, so run it off the client thread; answers
 * arrive on OkHttp threads. The cards read {@link #queued} without touching the disk.
 */
@Slf4j
class SubmissionSender
{
	interface Listener
	{
		/** A chat line, red with the notifier for a problem. */
		void tell(ProblemNotices.Notice notice);

		/** What waits to send changed: refresh the cards. */
		void queueChanged();
	}

	/** What a send needs from the plugin's state at the time. */
	@Value
	static class Context
	{
		/** The discovered Events left on this install. */
		Set<Integer> muted;
		/** Event names by Event number, for the chat lines. */
		Map<Integer, String> eventNames;
		boolean chatOnCounted;
	}

	private final SubmissionQueue queue;
	private final FriendscapeApi api;
	private final Listener listener;
	/** Pushed out of the full queue this session, by account hash and then Event number. */
	private final Map<String, Map<Integer, Integer>> pushedOut = new ConcurrentHashMap<>();
	/** The queue's counts as of its last change, by account hash and then Event number. */
	private volatile Map<String, Map<Integer, Integer>> waiting;

	SubmissionSender(SubmissionQueue queue, FriendscapeApi api, Listener listener)
	{
		this.queue = queue;
		this.api = api;
		this.listener = listener;
		this.waiting = queue.waiting();
	}

	/**
	 * Keeps new Submissions that share one screenshot ({@code png} null when capture failed). Any
	 * the full queue pushes out are told about and noted on their cards.
	 */
	void add(List<QueuedSubmission> submissions, byte[] png) throws IOException
	{
		for (QueuedSubmission submission : submissions)
		{
			for (QueuedSubmission removed : queue.add(submission, png))
			{
				Map<Integer, Integer> byEvent = pushedOut.computeIfAbsent(removed.getAccountHash(), hash -> new ConcurrentHashMap<>());
				removed.getEvents().forEach(number -> byEvent.merge(number, 1, Integer::sum));
				listener.tell(new ProblemNotices.Notice("The send queue is full, so " + removed.getName()
					+ " was taken out of it. Upload it on the event page.", true));
			}
		}
		changed();
	}

	/** Sends every Submission of this account that is due, each settled by its answer. */
	void flush(long accountHash, Context context, Instant now)
	{
		for (QueuedSubmission submission : queue.takeDue(accountHash, now))
		{
			byte[] png;
			try
			{
				png = queue.screenshot(submission.getId());
			}
			catch (IOException e)
			{
				log.warn("Could not read the screenshot of queued Submission {}", submission.getId(), e);
				queue.failed(submission.getId(), now);
				continue;
			}
			boolean sent = api.sendSubmission(submission, png, context.getMuted(), new FriendscapeApi.SubmissionCallback()
			{
				@Override
				public void answered(SubmissionResponse response)
				{
					queue.remove(submission.getId());
					changed();
					response.notices(submission, context.getEventNames(), context.isChatOnCounted()).forEach(listener::tell);
				}

				@Override
				public void refused(int code)
				{
					log.warn("Submission {} refused with {}", submission.getId(), code);
					queue.remove(submission.getId());
					changed();
					listener.tell(new ProblemNotices.Notice("Friendscape refused " + submission.getName()
						+ ". Upload a screenshot on the event page to claim it.", true));
				}

				@Override
				public void failed()
				{
					// Backoff from the flush, not the answer: a slow failure waits no longer
					queue.failed(submission.getId(), now);
				}
			});
			if (!sent)
			{
				queue.release(submission.getId());
			}
		}
	}

	/**
	 * Drops this account's Submissions no discovered Event can count any more: gone from
	 * discovery (card removed) or past end plus Grace window.
	 */
	void prune(long accountHash, DiscoveryResponse discovery, Instant now)
	{
		if (!queue.prune(accountHash, discovery.keepUntil(), now).isEmpty())
		{
			changed();
		}
	}

	/** Calls cut off before they answered: due again at the next flush. */
	void cancelled()
	{
		queue.clearInFlight();
	}

	/** This account's queued and pushed-out Submissions by Event number, for the cards. */
	Map<Integer, EventCard.Queued> queued(long accountHash)
	{
		String hash = Long.toString(accountHash);
		Map<Integer, Integer> waitingHere = waiting.getOrDefault(hash, Map.of());
		Map<Integer, Integer> pushedOutHere = pushedOut.getOrDefault(hash, Map.of());
		Map<Integer, EventCard.Queued> queued = new HashMap<>();
		waitingHere.forEach((number, count) -> queued.put(number, new EventCard.Queued(count, pushedOutHere.getOrDefault(number, 0))));
		pushedOutHere.forEach((number, count) -> queued.putIfAbsent(number, new EventCard.Queued(0, count)));
		return queued;
	}

	private void changed()
	{
		waiting = queue.waiting();
		listener.queueChanged();
	}
}

package com.friendscape;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Finds the Tiles and Tiers the player's Teams completed since the last discovery (SPEC 10.4), for
 * a chat line and a toast each. A board seen for the first time this session only sets the mark,
 * so logging in never replays old completions. Safe to call from OkHttp threads.
 */
class TeamCompletions
{
	/** The Tier each Team last had per position, by Event number and Team id. */
	private final Map<String, int[]> seen = new HashMap<>();

	synchronized List<String> check(DiscoveryResponse discovery, Set<Integer> left)
	{
		List<String> told = new ArrayList<>();
		for (DiscoveryResponse.DiscoveredEvent event : discovery.events())
		{
			DiscoveryResponse.Board board = event.getBoard();
			if (board == null || left.contains(event.getNumber()))
			{
				continue;
			}
			for (DiscoveryResponse.BoardTeam team : board.mine())
			{
				int[] tiers = new int[board.side() * board.side()];
				for (int position = 0; position < tiers.length; position++)
				{
					tiers[position] = team.tier(position);
				}
				int[] before = seen.put(event.getNumber() + ":" + team.getTeam(), tiers);
				if (before == null || before.length != tiers.length)
				{
					continue;
				}
				for (int position = 0; position < tiers.length; position++)
				{
					DiscoveryResponse.BoardTile tile = board.tile(position + 1);
					if (tile != null && tiers[position] > before[position])
					{
						told.add(text(event, team, tile, tiers[position]));
					}
				}
			}
		}
		return told;
	}

	private static String text(DiscoveryResponse.DiscoveredEvent event, DiscoveryResponse.BoardTeam team,
		DiscoveryResponse.BoardTile tile, int tier)
	{
		String where = "Tile " + tile.getNumber() + " (" + tile.getName() + ") in " + event.getName() + ".";
		return tile.getTiers() > 1
			? team.getName() + " reached Tier " + tier + " of " + tile.getTiers() + " on " + where
			: team.getName() + " completed " + where;
	}

	/** A new session: boards are seen afresh. */
	synchronized void reset()
	{
		seen.clear();
	}
}

package com.friendscape;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * What a Submission could count for (SPEC 10.3): only drops that some open Tile watches are sent.
 * Built from discovery, so it is as fresh as the last poll. Immutable.
 */
final class WatchList
{
	static final WatchList EMPTY = new WatchList(Map.of(), Map.of(), Set.of());

	/** Event numbers by watched item id. */
	private final Map<Integer, Set<Integer>> eventsById;
	/** Item id by lower-case name; null where two watched ids share the name. */
	private final Map<String, Integer> idByName;
	private final Set<Integer> clogSlotEvents;

	private WatchList(Map<Integer, Set<Integer>> eventsById, Map<String, Integer> idByName, Set<Integer> clogSlotEvents)
	{
		this.eventsById = eventsById;
		this.idByName = idByName;
		this.clogSlotEvents = clogSlotEvents;
	}

	/**
	 * The watch of every Live Event still on its Roster and not left. A held entry still watches:
	 * its Submissions are kept and count if the identity check settles in the player's favour.
	 */
	static WatchList of(DiscoveryResponse discovery, Set<Integer> left)
	{
		if (discovery == null)
		{
			return EMPTY;
		}
		Map<Integer, Set<Integer>> eventsById = new HashMap<>();
		Map<String, Integer> idByName = new HashMap<>();
		Set<Integer> clogSlotEvents = new HashSet<>();
		for (DiscoveryResponse.DiscoveredEvent event : discovery.events())
		{
			DiscoveryResponse.Watch watch = event.getWatch();
			if (watch == null || left.contains(event.getNumber())
				|| !DiscoveryResponse.LIVE.equals(event.getPhase())
				|| DiscoveryResponse.REMOVED.equals(event.getEntry()))
			{
				continue;
			}
			if (watch.isClogSlots())
			{
				clogSlotEvents.add(event.getNumber());
			}
			if (watch.getItems() == null)
			{
				continue;
			}
			for (DiscoveryResponse.WatchedItem item : watch.getItems())
			{
				eventsById.computeIfAbsent(item.getId(), id -> new HashSet<>()).add(event.getNumber());
				if (item.getName() != null)
				{
					String key = key(item.getName());
					Integer id = item.getId();
					boolean clash = idByName.containsKey(key) && !id.equals(idByName.get(key));
					idByName.put(key, clash ? null : id);
				}
			}
		}
		return new WatchList(eventsById, idByName, clogSlotEvents);
	}

	/** The Events watching this canonical item id; empty when none does. */
	Set<Integer> eventsFor(int itemId)
	{
		return eventsById.getOrDefault(itemId, Set.of());
	}

	/** The watched id a chat line's item name means, or null when none or more than one. */
	Integer idForName(String name)
	{
		return idByName.get(key(name));
	}

	/** The Events where some open Tile counts any new collection log slot. */
	Set<Integer> clogSlotEvents()
	{
		return clogSlotEvents;
	}

	private static String key(String name)
	{
		return name.trim().toLowerCase(Locale.ROOT);
	}
}

package com.friendscape;

import java.util.EnumSet;
import java.util.Set;
import net.runelite.api.WorldType;

/**
 * Decides whether progress on a world counts for Events. Leagues and other special worlds run on
 * separate characters or temporary progress, so nothing from them is ever sent.
 */
final class WorldFilter
{
	private static final Set<WorldType> EXCLUDED = EnumSet.of(
		WorldType.SEASONAL,
		WorldType.DEADMAN,
		WorldType.FRESH_START_WORLD,
		WorldType.TOURNAMENT_WORLD,
		WorldType.BETA_WORLD,
		WorldType.NOSAVE_MODE,
		WorldType.QUEST_SPEEDRUNNING,
		WorldType.PVP_ARENA,
		WorldType.LAST_MAN_STANDING
	);

	private WorldFilter()
	{
	}

	static boolean isTracked(Set<WorldType> worldTypes)
	{
		if (worldTypes == null)
		{
			return false;
		}
		for (WorldType type : worldTypes)
		{
			if (EXCLUDED.contains(type))
			{
				return false;
			}
		}
		return true;
	}
}

package com.friendscape;

import java.time.Duration;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;

/**
 * Decides which absolute skill XP to send (SPEC 5.2): every skill at login, then the skills that
 * changed, at most once per {@link #SEND_INTERVAL} while XP changes. Each send adds {@code overall}
 * as the sum of every skill. Keys are the server's skill slugs, e.g. {@code attack}.
 */
class XpTracker
{
	static final Duration SEND_INTERVAL = Duration.ofSeconds(60);
	static final String OVERALL = "overall";

	private final Map<String, Long> known = new HashMap<>();
	private final Map<String, Long> changed = new HashMap<>();
	private Instant lastSent;

	/**
	 * Records a skill's XP from {@code StatChanged}. Ignored until {@link #takeAll} has primed the
	 * tracker, since the login Reading covers everything before it.
	 */
	synchronized void observe(String skill, long xp)
	{
		if (lastSent == null)
		{
			return;
		}
		Long before = known.put(skill, xp);
		if (before == null || before != xp)
		{
			changed.put(skill, xp);
		}
	}

	/** Whether changed skills are waiting and the last send was at least a minute ago. */
	synchronized boolean due(Instant now)
	{
		return !changed.isEmpty() && lastSent != null && !now.isBefore(lastSent.plus(SEND_INTERVAL));
	}

	/** Every skill, for the login or start Reading. Primes the tracker and clears what changed. */
	synchronized Map<String, Long> takeAll(Map<String, Long> skills, Instant now)
	{
		known.clear();
		known.putAll(skills);
		changed.clear();
		lastSent = now;
		return withOverall(new HashMap<>(known));
	}

	/** The skills changed since the last send, empty if none; the logout Reading ignores the minute. */
	synchronized Map<String, Long> takeChanged(Instant now)
	{
		if (changed.isEmpty())
		{
			return Map.of();
		}
		Map<String, Long> sent = withOverall(new HashMap<>(changed));
		changed.clear();
		lastSent = now;
		return sent;
	}

	/** Forgets everything: the next Reading must be a {@link #takeAll}. */
	synchronized void reset()
	{
		known.clear();
		changed.clear();
		lastSent = null;
	}

	private Map<String, Long> withOverall(Map<String, Long> skills)
	{
		long overall = 0;
		for (long xp : known.values())
		{
			overall += xp;
		}
		skills.put(OVERALL, overall);
		return skills;
	}
}

package com.friendscape;

import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import org.junit.Test;

public class CodewordOverlaysTest
{
	private final List<String> added = new ArrayList<>();
	private final List<String> removed = new ArrayList<>();
	private final CodewordOverlays overlays = new CodewordOverlays(
		overlay -> added.add(overlay.getName()), overlay -> removed.add(overlay.getName()),
		number -> new CodewordOverlay(null, number, () -> true, new FriendscapeConfig()
		{
		}));

	private static EventCard card(int number, boolean live, String codeword)
	{
		return new EventCard(number, "Event " + number, live ? CardState.TRACKING : CardState.ENDED, "", List.of(),
			List.of(), "", null, EventCard.OPEN_EVENT_PAGE, false, false, live, null, false, codeword);
	}

	private static Map<Integer, String> codewords(Object... pairs)
	{
		Map<Integer, String> map = new LinkedHashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			map.put((Integer) pairs[i], (String) pairs[i + 1]);
		}
		return map;
	}

	@Test
	public void wantsOneOverlayPerCardWithACodewordNotHidden()
	{
		List<EventCard> cards = List.of(card(111111, true, "Mithril"), card(222222, true, null),
			card(333333, true, "Adamant"), card(444444, true, "Rune"));

		assertEquals(codewords(111111, "Mithril", 444444, "Rune"), CodewordOverlays.wanted(cards, Set.of(333333)));
	}

	@Test
	public void addsAnOverlayNamedByEventNumberAndRemovesItOnceNotWanted()
	{
		overlays.show(codewords(111111, "Mithril", 222222, "Rune"));
		assertEquals(List.of("friendscape-codeword-111111", "friendscape-codeword-222222"), added);

		overlays.show(codewords(222222, "Rune"));
		assertEquals(List.of("friendscape-codeword-111111"), removed);

		overlays.show(Map.of());
		assertEquals(List.of("friendscape-codeword-111111", "friendscape-codeword-222222"), removed);
	}

	@Test
	public void keepsAnOverlayAcrossUpdatesAndFollowsANewCodeword()
	{
		overlays.show(codewords(111111, "Mithril"));
		CodewordOverlay first = overlays.overlay(111111);

		overlays.show(codewords(111111, "Adamant"));

		assertEquals(1, added.size());
		assertSame(first, overlays.overlay(111111));
		assertEquals("Adamant", first.getCodeword());
	}

	@Test
	public void closeRemovesEveryOverlayAndAddsNoneAfter()
	{
		overlays.show(codewords(111111, "Mithril", 222222, "Rune"));

		overlays.close();

		assertEquals(2, removed.size());
		overlays.show(codewords(111111, "Mithril"));
		assertEquals(2, added.size());
	}

	@Test
	public void timestampsInUtcToTheMinute()
	{
		assertEquals("2026-11-03 12:05 UTC", CodewordOverlay.timestamp(Instant.parse("2026-11-03T12:05:59.900Z")));
	}
}

package com.friendscape;

import com.google.gson.Gson;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class DiscoveryResponseTest
{
	private static final Gson GSON = new Gson();
	private static final Instant NOW = Instant.parse("2026-11-03T12:00:00Z");

	private static String event(int number, String phase, String entry, String extra)
	{
		return "{\"number\":" + number + ",\"name\":\"Event " + number + "\",\"format\":\"sotw\",\"phase\":\"" + phase + "\","
			+ "\"startsAt\":\"2026-11-01T18:00:00.000Z\",\"endsAt\":\"2026-11-08T18:00:00.000Z\","
			+ "\"entry\":\"" + entry + "\"" + (extra.isEmpty() ? "" : "," + extra) + "}";
	}

	private static DiscoveryResponse parse(String... events)
	{
		return GSON.fromJson("{\"rsn\":\"Iron Man\",\"events\":[" + String.join(",", events) + "]}",
			DiscoveryResponse.class);
	}

	private static List<Integer> numbers(List<EventCard> cards)
	{
		return cards.stream().map(EventCard::getNumber).collect(Collectors.toList());
	}

	@Test
	public void makesOneCardPerEventInServerOrder()
	{
		DiscoveryResponse response = parse(event(222222, "live", "on_roster", ""), event(111111, "scheduled", "on_roster", ""));

		assertEquals(List.of(222222, 111111), numbers(response.cards(Set.of(), Map.of(), NOW, ZoneOffset.UTC)));
	}

	@Test
	public void ordersCardsLiveThenVotingThenScheduledThenFinishedThenLeft()
	{
		int left = 100001;
		int finalized = 100002;
		int removed = 100003;
		int ended = 100004;
		int unscheduled = 100005;
		int soon = 100006;
		int live = 100007;
		int held = 100008;
		int votingLater = 100009;
		int votingSooner = 100010;
		int leftVoting = 100011;
		DiscoveryResponse response = parse(
			event(left, "live", "on_roster", ""),
			event(finalized, "finalized", "on_roster", "\"finalizedAt\":\"2026-11-02T12:00:00.000Z\""),
			event(removed, "live", "removed", ""),
			event(ended, "ended", "on_roster", ""),
			event(unscheduled, "published", "on_roster", ""),
			event(votingLater, "published", "on_roster", vote("2026-11-06T18:00:00.000Z")),
			event(soon, "scheduled", "on_roster", ""),
			event(live, "live", "on_roster", ""),
			event(leftVoting, "published", "on_roster", vote("2026-11-04T18:00:00.000Z")),
			event(votingSooner, "published", "on_roster", vote("2026-11-05T18:00:00.000Z")),
			event(held, "live", "held", ""));

		assertEquals(List.of(live, held, votingSooner, votingLater, soon, unscheduled, ended, finalized, left, removed,
			leftVoting), numbers(response.cards(Set.of(left, leftVoting), Map.of(), NOW, ZoneOffset.UTC)));
	}

	private static String vote(String closesAt)
	{
		return "\"vote\":{\"closesAt\":\"" + closesAt + "\",\"open\":false,\"candidates\":[]}";
	}

	@Test
	public void removesAFinalizedCardSevenDaysAfterFinalize()
	{
		DiscoveryResponse response = parse(
			event(111111, "finalized", "on_roster", "\"finalizedAt\":\"2026-10-28T12:00:01.000Z\""),
			event(222222, "finalized", "on_roster", "\"finalizedAt\":\"2026-10-27T12:00:00.000Z\""));

		assertEquals(List.of(111111), numbers(response.cards(Set.of(), Map.of(), NOW, ZoneOffset.UTC)));
	}

	@Test
	public void marksLeftCards()
	{
		DiscoveryResponse response = parse(event(111111, "live", "on_roster", ""), event(222222, "live", "on_roster", ""));

		List<EventCard> cards = response.cards(Set.of(222222), Map.of(), NOW, ZoneOffset.UTC);

		assertEquals(CardState.TRACKING, cards.get(0).getState());
		assertEquals(CardState.LEFT, cards.get(1).getState());
	}

	@Test
	public void namesTheLiveEventsWhetherLeftOrRemoved()
	{
		DiscoveryResponse response = parse(
			event(111111, "live", "on_roster", ""),
			event(222222, "live", "removed", ""),
			event(333333, "ended", "on_roster", ""),
			event(444444, "scheduled", "on_roster", ""),
			event(555555, "live", "held", ""));

		assertEquals(Set.of(111111, 222222, 555555), response.liveNumbers());
		assertEquals(Set.of(), GSON.fromJson("{}", DiscoveryResponse.class).liveNumbers());
	}

	@Test
	public void isEmptyWithNoEvents()
	{
		assertTrue(parse().cards(Set.of(), Map.of(), NOW, ZoneOffset.UTC).isEmpty());
		assertTrue(GSON.fromJson("{}", DiscoveryResponse.class).cards(Set.of(), Map.of(), NOW, ZoneOffset.UTC).isEmpty());
	}

	@Test
	public void wantsReadingsWhileAnEventNotLeftCanStillTakeThem()
	{
		assertTrue(parse(event(111111, "live", "on_roster", "")).wantsReadings(Set.of(), NOW));
		assertTrue(parse(event(111111, "scheduled", "on_roster", "")).wantsReadings(Set.of(), NOW));
		// A held claimant's Readings settle the name-reuse check
		assertTrue(parse(event(111111, "live", "held", "")).wantsReadings(Set.of(), NOW));
		assertTrue(parse(event(111111, "published", "on_roster", "")).wantsReadings(Set.of(), NOW));
	}

	@Test
	public void wantsNoReadingsWhenEveryEventIsLeftEndedOrRemoved()
	{
		assertFalse(parse().wantsReadings(Set.of(), NOW));
		assertFalse(parse(event(111111, "live", "on_roster", "")).wantsReadings(Set.of(111111), NOW));
		assertFalse(parse(event(111111, "live", "removed", "")).wantsReadings(Set.of(), NOW));
		assertFalse(parse(event(111111, "ended", "on_roster", "\"endsAt\":\"2026-11-03T11:57:00.000Z\""))
			.wantsReadings(Set.of(), NOW));
		assertFalse(parse(event(111111, "finalized", "on_roster", "")).wantsReadings(Set.of(), NOW));
	}

	@Test
	public void stillWantsTheEndReadingJustAfterEnd()
	{
		DiscoveryResponse response = parse(event(111111, "ended", "on_roster", "\"endsAt\":\"2026-11-03T11:59:00.000Z\""));

		assertTrue(response.wantsReadings(Set.of(), NOW));
	}

	@Test
	public void namesTheLeftEventsItFound()
	{
		DiscoveryResponse response = parse(event(111111, "live", "on_roster", ""), event(222222, "live", "on_roster", ""));

		assertEquals(Set.of(222222), response.muted(Set.of(222222, 333333)));
	}

	@Test
	public void schedulesTheStartReadingOfAnEventScheduledAfterLogin()
	{
		DiscoveryResponse response = parse(
			event(111111, "scheduled", "on_roster", "\"startsAt\":\"2026-11-04T18:00:00.000Z\""),
			event(222222, "scheduled", "on_roster", "\"startsAt\":\"2026-11-03T18:00:00.000Z\""));

		ReadingsResponse readings = response.asReadings(Set.of(222222));

		assertEquals(Instant.parse("2026-11-04T18:00:02Z"), readings.nextMomentReading(NOW));
	}

	@Test
	public void givesEachEventTheStatusAReadingWouldAnswer()
	{
		DiscoveryResponse response = parse(
			event(111111, "live", "on_roster", ""),
			event(222222, "scheduled", "on_roster", ""),
			event(333333, "ended", "held", ""),
			event(444444, "live", "held", ""),
			event(555555, "live", "removed", ""),
			event(666666, "finalized", "on_roster", ""));

		List<String> statuses = response.asReadings(Set.of()).getEvents().stream()
			.map(ReadingsResponse.EventReading::getStatus).collect(Collectors.toList());

		assertEquals(List.of("counted", "not_started", "ended", "held", "not_on_roster", "ended"), statuses);
	}

	private static final String LIST_VOTE = "\"vote\":{\"closesAt\":\"2026-11-05T18:00:00.000Z\",\"open\":false,"
		+ "\"candidates\":[{\"id\":1,\"name\":\"Fishing\",\"icon\":{\"kind\":\"xp\",\"skill\":\"fishing\"},\"count\":2,\"cooling\":false},"
		+ "{\"id\":2,\"name\":\"Mining\",\"icon\":null,\"count\":0,\"cooling\":true}],\"choice\":1,\"later\":true}";

	@Test
	public void readsAVoteAndIgnoresFieldsItDoesNotKnow()
	{
		DiscoveryResponse response = parse(event(111111, "published", "on_roster", LIST_VOTE + ",\"newer\":{\"x\":1}"));

		DiscoveryResponse.Vote vote = response.events().get(0).getVote();
		assertEquals(Integer.valueOf(1), vote.getChoice());
		assertEquals("Fishing", vote.candidates().get(0).getName());
		assertEquals(2, vote.candidates().get(0).votes());
		assertTrue(vote.candidates().get(1).isCooling());
	}

	@Test
	public void swapsInTheVoteAVoteAnswered()
	{
		DiscoveryResponse response = parse(event(111111, "published", "on_roster", LIST_VOTE),
			event(222222, "live", "on_roster", ""));
		DiscoveryResponse.Vote answered = GSON.fromJson("{\"closesAt\":\"2026-11-05T18:00:00.000Z\",\"open\":false,"
			+ "\"candidates\":[],\"choice\":2}", DiscoveryResponse.Vote.class);

		DiscoveryResponse swapped = response.withVote(111111, answered);

		assertEquals(Integer.valueOf(2), swapped.events().get(0).getVote().getChoice());
		assertEquals(null, swapped.events().get(1).getVote());
		assertEquals("Iron Man", swapped.getRsn());
	}

	private static DiscoveryResponse.Vote anyVote(String counts)
	{
		String[] names = {"Attack", "Defence", "Strength", "Hitpoints", "Ranged"};
		String[] each = counts.split(",");
		List<String> candidates = new ArrayList<>();
		for (int i = 0; i < names.length; i++)
		{
			candidates.add("{\"id\":" + (i + 1) + ",\"name\":\"" + names[i] + "\""
				+ (each[i].equals("-") ? "" : ",\"count\":" + each[i]) + ",\"cooling\":false}");
		}
		return GSON.fromJson("{\"closesAt\":\"2026-11-05T18:00:00.000Z\",\"open\":true,\"candidates\":["
			+ String.join(",", candidates) + "],\"choice\":null}", DiscoveryResponse.Vote.class);
	}

	@Test
	public void talliesTheTopThreeVotedByCountTiesInBallotOrder()
	{
		assertEquals(List.of("Strength: 4", "Defence: 2", "Ranged: 2", "+1 more with votes"),
			anyVote("1,2,4,-,2").tally());
		assertEquals(List.of("Hitpoints: 1"), anyVote("-,-,-,1,-").tally());
		assertEquals(List.of("No votes yet"), anyVote("-,-,-,-,-").tally());
	}
}

