{
	private static final Gson GSON = new Gson();

	private final ProblemNotices notices = new ProblemNotices();

	/** Pairs of Event number and Roster entry state. */
	private static DiscoveryResponse discovery(Object... numberAndEntry)
	{
		StringBuilder events = new StringBuilder();
		for (int i = 0; i < numberAndEntry.length; i += 2)
		{
			events.append(i == 0 ? "" : ",").append("{\"number\":").append(numberAndEntry[i])
				.append(",\"name\":\"Event ").append(numberAndEntry[i])
				.append("\",\"phase\":\"live\",\"entry\":\"").append(numberAndEntry[i + 1]).append("\"}");
		}
		return GSON.fromJson("{\"events\":[" + events + "]}", DiscoveryResponse.class);
	}

	@Test
	public void warnsOfAHeldMismatchOncePerSessionInRedWithTheNotifier()
	{
		List<ProblemNotices.Notice> first = notices.check(discovery(111111, "held"), Set.of());
		List<ProblemNotices.Notice> again = notices.check(discovery(111111, "held"), Set.of());

		assertEquals(1, first.size());
		assertTrue(first.get(0).isProblem());
		assertTrue(first.get(0).getText().contains("Event 111111"));
		assertTrue(again.isEmpty());
	}

	@Test
	public void saysNotOnRosterOncePerSessionQuietly()
	{
		List<ProblemNotices.Notice> first = notices.check(discovery(111111, "removed"), Set.of());

		assertEquals(1, first.size());
		assertEquals(false, first.get(0).isProblem());
		assertTrue(notices.check(discovery(111111, "removed"), Set.of()).isEmpty());
	}

	@Test
	public void saysNothingForTrackedOrLeftEvents()
	{
		assertTrue(notices.check(discovery(111111, "on_roster", 222222, "held"), Set.of(222222)).isEmpty());
	}

	@Test
	public void warnsAgainInANewSession()
	{
		notices.check(discovery(111111, "held"), Set.of());

		notices.reset();

		assertEquals(1, notices.check(discovery(111111, "held"), Set.of()).size());
	}

	@Test
	public void warnsPerEvent()
	{
		notices.check(discovery(111111, "held"), Set.of());

		assertEquals(1, notices.check(discovery(111111, "held", 222222, "held"), Set.of()).size());
	}
}

package com.friendscape;

import com.google.gson.Gson;
import java.time.Instant;
import java.util.EnumSet;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class ReadingsResponseTest
{
	private static final Gson GSON = new Gson();
	private static final Instant NOW = Instant.parse("2026-11-01T17:00:00Z");

	private static ReadingsResponse parse(String json)
	{
		return GSON.fromJson(json, ReadingsResponse.class);
	}

	@Test
	public void readsEachEventStatus()
	{
		ReadingsResponse response = parse("{\"rsn\":\"Iron Man\",\"events\":["
			+ "{\"number\":123456,\"status\":\"counted\",\"startsAt\":\"2026-11-01T00:00:00.000Z\",\"endsAt\":null}]}");

		assertEquals(123456, response.getEvents().get(0).getNumber());
		assertEquals("counted", response.getEvents().get(0).getStatus());
	}

	@Test
	public void schedulesTheStartReadingAtTheEarliestStartToCome()
	{
		ReadingsResponse response = parse("{\"events\":["
			+ "{\"number\":222222,\"status\":\"not_started\",\"startsAt\":\"2026-11-02T18:00:00.000Z\"},"
			+ "{\"number\":111111,\"status\":\"not_started\",\"startsAt\":\"2026-11-01T18:00:00.000Z\"},"
			+ "{\"number\":333333,\"status\":\"counted\",\"startsAt\":\"2026-10-01T18:00:00.000Z\"}]}");

		assertEquals(Instant.parse("2026-11-01T18:00:02Z"), response.nextMomentReading(NOW));
	}

	@Test
	public void schedulesNoStartReadingForAnEventWithoutAStart()
	{
		ReadingsResponse response = parse("{\"events\":[{\"number\":111111,\"status\":\"not_started\",\"startsAt\":null}]}");

		assertNull(response.nextMomentReading(NOW));
	}

	@Test
	public void retriesShortlyWhenTheServerHasNotReachedAStartThisClockHasPassed()
	{
		ReadingsResponse response = parse("{\"events\":["
			+ "{\"number\":111111,\"status\":\"not_started\",\"startsAt\":\"2026-11-01T16:59:59.000Z\"}]}");

		assertEquals(NOW.plusSeconds(10), response.nextMomentReading(NOW));
	}

	@Test
	public void schedulesTheEndReadingAtTheEndOfACountedEvent()
	{
		ReadingsResponse response = parse("{\"events\":["
			+ "{\"number\":111111,\"status\":\"counted\",\"startsAt\":\"2026-10-01T18:00:00.000Z\",\"endsAt\":\"2026-11-01T18:00:00.000Z\"},"
			+ "{\"number\":222222,\"status\":\"held\",\"startsAt\":\"2026-10-01T18:00:00.000Z\",\"endsAt\":\"2026-11-01T17:30:00.000Z\"},"
			+ "{\"number\":333333,\"status\":\"ended\",\"startsAt\":\"2026-10-01T18:00:00.000Z\",\"endsAt\":\"2026-11-01T16:00:00.000Z\"}]}");

		assertEquals(Instant.parse("2026-11-01T18:00:02Z"), response.nextMomentReading(NOW));
	}

	@Test
	public void schedulesWhicheverMomentComesFirst()
	{
		ReadingsResponse response = parse("{\"events\":["
			+ "{\"number\":111111,\"status\":\"not_started\",\"startsAt\":\"2026-11-01T19:00:00.000Z\"},"
			+ "{\"number\":222222,\"status\":\"counted\",\"endsAt\":\"2026-11-01T18:00:00.000Z\"}]}");

		assertEquals(Instant.parse("2026-11-01T18:00:02Z"), response.nextMomentReading(NOW));
	}

	@Test
	public void retriesShortlyWhenTheServerHasNotReachedAnEndThisClockHasPassed()
	{
		ReadingsResponse response = parse("{\"events\":["
			+ "{\"number\":111111,\"status\":\"counted\",\"endsAt\":\"2026-11-01T16:59:59.000Z\"}]}");

		assertEquals(NOW.plusSeconds(10), response.nextMomentReading(NOW));
	}

	@Test
	public void marksTheMomentsThisClockHasPassed()
	{
		ReadingsResponse response = parse("{\"events\":["
			+ "{\"number\":111111,\"status\":\"not_started\",\"startsAt\":\"2026-11-01T17:00:00.000Z\"},"
			+ "{\"number\":222222,\"status\":\"counted\",\"endsAt\":\"2026-11-01T18:00:00.000Z\"}]}");

		assertEquals(EnumSet.of(Moment.START), response.momentsDue(NOW));
		assertEquals(EnumSet.of(Moment.START, Moment.END), response.momentsDue(Instant.parse("2026-11-01T18:00:02Z")));
	}

	@Test
	public void marksNothingBeforeAnyMoment()
	{
		ReadingsResponse response = parse("{\"events\":["
			+ "{\"number\":111111,\"status\":\"not_started\",\"startsAt\":\"2026-11-01T18:00:00.000Z\"},"
			+ "{\"number\":222222,\"status\":\"ended\",\"endsAt\":\"2026-11-01T16:00:00.000Z\"}]}");

		assertEquals(Set.of(), response.momentsDue(NOW));
		assertEquals(Set.of(), parse("{}").momentsDue(NOW));
	}

	@Test
	public void schedulesNothingForAnEmptyResponse()
	{
		assertNull(parse("{\"rsn\":\"Nobody\",\"events\":[]}").nextMomentReading(NOW));
		assertNull(parse("{}").nextMomentReading(NOW));
	}

	@Test
	public void schedulesNothingForAnEventLeftOnThisInstall()
	{
		ReadingsResponse response = parse("{\"events\":["
			+ "{\"number\":100001,\"status\":\"not_started\",\"startsAt\":\"2026-11-01T18:00:00.000Z\"},"
			+ "{\"number\":100002,\"status\":\"not_started\",\"startsAt\":\"2026-11-02T18:00:00.000Z\"}]}");

		assertEquals(Instant.parse("2026-11-02T18:00:02Z"), response.without(Set.of(100001)).nextMomentReading(NOW));
		assertEquals(java.util.Map.of(100001, "not_started", 100002, "not_started"), response.statuses());
	}
}

package com.friendscape;

import java.util.Set;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class StoredEventNumbersTest
{
	@Test
	public void readsAndWritesTheStoredList()
	{
		assertEquals(Set.of(), StoredEventNumbers.parse(null));
		assertEquals(Set.of(), StoredEventNumbers.parse(""));
		assertEquals(Set.of(123456, 654321), StoredEventNumbers.parse("123456,654321"));
		assertEquals(Set.of(123456, 654321), StoredEventNumbers.parse(StoredEventNumbers.format(Set.of(654321, 123456))));
		assertEquals("123456,654321", StoredEventNumbers.format(Set.of(654321, 123456)));
	}

	@Test
	public void dropsStaleSlugsAndAnythingElseNotAnEventNumber()
	{
		assertEquals(Set.of(), StoredEventNumbers.parse("my-bingo-ab12,botw-7"));
		assertEquals(Set.of(123456, 999999),
			StoredEventNumbers.parse("my-bingo-ab12,123456,099999,12345,1234567,1e5,+123456, 123456,999999,"));
	}

	@Test
	public void knowsAnEventNumber()
	{
		assertEquals(true, StoredEventNumbers.isEventNumber(100000));
		assertEquals(true, StoredEventNumbers.isEventNumber(999999));
		assertEquals(false, StoredEventNumbers.isEventNumber(99999));
		assertEquals(false, StoredEventNumbers.isEventNumber(1000000));
		assertEquals(false, StoredEventNumbers.isEventNumber(null));
	}

	@Test
	public void prunesToTheKeptNumbers()
	{
		assertEquals("123456", StoredEventNumbers.prune("123456,654321", Set.of(123456, 111111)));
		assertEquals("", StoredEventNumbers.prune("123456", Set.of()));
		assertEquals("", StoredEventNumbers.prune("", Set.of(123456)));
	}
}

package com.friendscape;

import com.google.gson.Gson;
import java.util.List;
import java.util.Set;
import net.runelite.client.game.ItemStack;
import net.runelite.http.api.loottracker.LootRecordType;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class SubmissionDetectorTest
{
	private static final int VISAGE = 11286;
	private static final int NOTED_VISAGE = 11287;
	private static final int SNAKELING = 12921;

	private SubmissionDetector detector;

	@Before
	public void setUp()
	{
		// Notes canonicalize to the item, as ItemManager does
		detector = new SubmissionDetector(id -> id == NOTED_VISAGE ? VISAGE : id, id -> "Item " + id);
		watch("{\"items\":[{\"id\":11286,\"name\":\"Draconic visage\"},{\"id\":12921,\"name\":\"Pet snakeling\"}],"
			+ "\"clogSlots\":false}");
	}

	private void watch(String watch)
	{
		String json = "{\"events\":[{\"number\":123456,\"phase\":\"live\",\"entry\":\"on_roster\",\"watch\":" + watch + "}]}";
		detector.setWatch(WatchList.of(new Gson().fromJson(json, DiscoveryResponse.class), Set.of()));
	}

	private static SubmissionDetector.Drop item(int id, String name, int quantity)
	{
		return new SubmissionDetector.Drop(SubmissionDetector.Kind.ITEM, id, name, quantity, Set.of(123456));
	}

	@Test
	public void sendsOnlyWatchedItemsFromLoot()
	{
		List<SubmissionDetector.Drop> drops = detector.loot(List.of(new ItemStack(526, 1), new ItemStack(VISAGE, 1)));

		assertEquals(List.of(item(VISAGE, "Item 11286", 1)), drops);
	}

	@Test
	public void canonicalizesIdsAndAddsUpStacksOfOneItem()
	{
		List<SubmissionDetector.Drop> drops = detector.loot(List.of(new ItemStack(NOTED_VISAGE, 2), new ItemStack(VISAGE, 1)));

		assertEquals(List.of(item(VISAGE, "Item 11286", 3)), drops);
	}

	@Test
	public void namesAPetFromTheLineAfterThePetLine()
	{
		assertEquals(List.of(), detector.chat("You have a funny feeling like you're being followed."));

		assertEquals(List.of(item(SNAKELING, "Pet snakeling", 1)), detector.chat("Untradeable drop: Pet snakeling"));
		// The collection log line for the same pet is not a second pet
		assertEquals(List.of(), detector.chat("New item added to your collection log: Pet snakeling"));
	}

	@Test
	public void doesNotTakeAnItemTheLootAlreadySentForThePet()
	{
		watch("{\"items\":[{\"id\":11286,\"name\":\"Draconic visage\"},{\"id\":12921,\"name\":\"Pet snakeling\"}],"
			+ "\"clogSlots\":false}");
		detector.loot(List.of(new ItemStack(VISAGE, 1)));
		detector.chat("You have a funny feeling like you're being followed.");

		// The visage's own untradeable line is not the pet's, and the pet line still waits for its name
		assertEquals(List.of(), detector.chat("Untradeable drop: Draconic visage"));
		assertEquals(List.of(item(SNAKELING, "Pet snakeling", 1)), detector.chat("Untradeable drop: Pet snakeling"));
	}

	@Test
	public void forgetsThePetLineAfterAFewTicks()
	{
		detector.chat("You have a funny feeling like you're being followed.");
		for (int i = 0; i < SubmissionDetector.PET_NAME_TICKS; i++)
		{
			detector.tick();
		}

		assertEquals(List.of(), detector.chat("Untradeable drop: Pet snakeling"));
	}

	@Test
	public void ignoresAnUntradeableDropWithoutAPetLine()
	{
		// Untradeable drops land on the floor and come through loot
		assertEquals(List.of(), detector.chat("Untradeable drop: Pet snakeling"));
	}

	@Test
	public void sendsANewClogSlotOnlyWhereSomeTileCountsSlots()
	{
		assertEquals(List.of(), detector.chat("New item added to your collection log: Dragon pickaxe"));

		watch("{\"items\":[{\"id\":11286,\"name\":\"Draconic visage\"}],\"clogSlots\":true}");

		assertEquals(List.of(new SubmissionDetector.Drop(SubmissionDetector.Kind.CLOG_SLOT, null, "Dragon pickaxe", 1,
				Set.of(123456))),
			detector.chat("New item added to your collection log: Dragon pickaxe"));
		assertEquals(List.of(new SubmissionDetector.Drop(SubmissionDetector.Kind.CLOG_SLOT, VISAGE, "Draconic visage", 1,
				Set.of(123456))),
			detector.chat("New item added to your collection log: Draconic visage"));
	}

	@Test
	public void takesLootFromChestsAndPickpocketsButNotKillsCoveredElsewhere()
	{
		assertTrue(SubmissionDetector.countsLoot(LootRecordType.EVENT));
		assertTrue(SubmissionDetector.countsLoot(LootRecordType.PICKPOCKET));
		// NPC kills come through ServerNpcLoot; player kills are not the player's own drops
		assertFalse(SubmissionDetector.countsLoot(LootRecordType.NPC));
		assertFalse(SubmissionDetector.countsLoot(LootRecordType.PLAYER));
		assertFalse(SubmissionDetector.countsLoot(LootRecordType.UNKNOWN));
	}
}

package com.friendscape;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.time.Duration;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.Set;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class SubmissionQueueTest
{
	private static final Instant NOW = Instant.parse("2026-11-03T12:00:00Z");
	private static final long HASH = 7L;
	private static final byte[] PNG = {(byte) 0x89, 'P', 'N', 'G'};
	private static final int BINGO = 123456;
	private static final int OTHER = 234567;
	private static final int LIVE = 345678;
	private static final int OVER = 456789;
	private static final int DELETED = 567890;
	private static final int NO_END = 678901;

	@Rule
	public TemporaryFolder folder = new TemporaryFolder();

	private File dir;
	private SubmissionQueue queue;

	@Before
	public void setUp() throws IOException
	{
		dir = new File(folder.getRoot(), "submissions");
		queue = open();
	}

	private SubmissionQueue open() throws IOException
	{
		return SubmissionQueue.open(dir, new Gson());
	}

	private static QueuedSubmission entry(String id, Instant capturedAt, Integer... events)
	{
		return new QueuedSubmission(id, Long.toString(HASH), "Iron Man", "item", 11286, "Draconic visage", 1,
			capturedAt.toString(), List.of(events));
	}

	@Test
	public void keepsAnEntryAndItsScreenshotAcrossRestarts() throws IOException
	{
		queue.add(entry("a", NOW, BINGO), PNG);

		SubmissionQueue reopened = open();

		assertEquals(List.of(entry("a", NOW, BINGO)), reopened.due(HASH, NOW));
		assertArrayEquals(PNG, reopened.screenshot("a"));
	}

	@Test
	public void keepsAnEntryWhoseScreenshotFailed() throws IOException
	{
		queue.add(entry("a", NOW, BINGO), null);

		assertEquals(1, open().due(HASH, NOW).size());
		assertNull(queue.screenshot("a"));
	}

	@Test
	public void dropsTheOldestPastTheCap() throws IOException
	{
		for (int i = 0; i < SubmissionQueue.CAP; i++)
		{
			assertEquals(List.of(), queue.add(entry("e" + i, NOW.plusSeconds(i), BINGO), PNG));
		}

		List<QueuedSubmission> dropped = queue.add(entry("new", NOW.plusSeconds(100), BINGO), PNG);

		assertEquals(List.of(entry("e0", NOW, BINGO)), dropped);
		assertEquals(SubmissionQueue.CAP, open().due(HASH, NOW.plusSeconds(100)).size());
		assertFalse(new File(dir, "e0.png").exists());
	}

	@Test
	public void sendsOnlyTheLoggedInAccountsEntries() throws IOException
	{
		queue.add(new QueuedSubmission("other", "8", "Alt", "item", 1, "x", 1, NOW.toString(), List.of(BINGO)), PNG);

		assertEquals(List.of(), queue.due(HASH, NOW));
	}

	@Test
	public void backsOffAfterEachFailedSend() throws IOException
	{
		queue.add(entry("a", NOW, BINGO), PNG);

		assertEquals(1, queue.takeDue(HASH, NOW).size());
		assertEquals("in flight, so a second flush takes nothing", List.of(), queue.takeDue(HASH, NOW));
		queue.failed("a", NOW);
		assertEquals(List.of(), queue.due(HASH, NOW.plus(SubmissionQueue.FIRST_RETRY).minusSeconds(1)));
		assertEquals(1, queue.due(HASH, NOW.plus(SubmissionQueue.FIRST_RETRY)).size());

		queue.takeDue(HASH, NOW.plus(SubmissionQueue.FIRST_RETRY));
		queue.failed("a", NOW);
		assertEquals("doubled", List.of(), queue.due(HASH, NOW.plus(SubmissionQueue.FIRST_RETRY)));
		assertEquals(1, queue.due(HASH, NOW.plus(SubmissionQueue.FIRST_RETRY.multipliedBy(2))).size());
	}

	@Test
	public void sendsAgainACallCutOffBeforeItAnswered() throws IOException
	{
		queue.add(entry("a", NOW, BINGO), PNG);
		queue.takeDue(HASH, NOW);

		queue.clearInFlight();

		assertEquals(1, queue.due(HASH, NOW).size());
	}

	@Test
	public void releasesASendThatNeverLeftWithoutBackoff() throws IOException
	{
		queue.add(entry("a", NOW, BINGO), PNG);
		queue.takeDue(HASH, NOW);

		queue.release("a");

		assertEquals(1, queue.due(HASH, NOW).size());
	}

	@Test
	public void removesAnAnsweredEntryAndItsScreenshot() throws IOException
	{
		queue.add(entry("a", NOW, BINGO), PNG);

		queue.remove("a");

		assertEquals(List.of(), open().due(HASH, NOW));
		assertEquals(0, dir.listFiles().length);
	}

	@Test
	public void prunesEntriesWhoseEventsAreGoneOrPastTheirGraceWindow() throws IOException
	{
		queue.add(entry("open", NOW, LIVE, OVER), PNG);
		queue.add(entry("over", NOW, OVER), PNG);
		queue.add(entry("gone", NOW, DELETED), PNG);
		queue.add(entry("unscheduled", NOW, NO_END), PNG);
		queue.add(new QueuedSubmission("alt", "8", "Alt", "item", 1, "x", 1, NOW.toString(), List.of(DELETED)), PNG);

		Map<Integer, Instant> keepUntil = new java.util.HashMap<>();
		keepUntil.put(LIVE, NOW.plus(Duration.ofDays(1)));
		keepUntil.put(OVER, NOW.minusSeconds(1));
		keepUntil.put(NO_END, null);
		List<QueuedSubmission> pruned = queue.prune(HASH, keepUntil, NOW);

		assertEquals(Set.of("over", "gone"), Set.of(pruned.get(0).getId(), pruned.get(1).getId()));
		assertEquals(Set.of("open", "unscheduled"), Set.of(queue.due(HASH, NOW).get(0).getId(), queue.due(HASH, NOW).get(1).getId()));
		assertEquals("another account's entries wait for its own discovery", 1, queue.due(8L, NOW).size());
	}

	@Test
	public void countsWhatIsWaitingPerEvent() throws IOException
	{
		queue.add(entry("a", NOW, BINGO, OTHER), PNG);
		queue.add(entry("b", NOW, BINGO), PNG);

		queue.add(new QueuedSubmission("alt", "8", "Alt", "item", 1, "x", 1, NOW.toString(), List.of(BINGO)), PNG);

		assertEquals(Map.of("7", Map.of(BINGO, 2, OTHER, 1), "8", Map.of(BINGO, 1)), queue.waiting());
	}

	@Test
	public void dropsEntriesStoredWithEventSlugsAtStart() throws IOException
	{
		queue.add(entry("a", NOW, BINGO), PNG);
		// Stored before Events were numbered: its Events are slugs, or text that is no Event number
		Files.write(new File(dir, "slugs.json").toPath(), ("{\"id\":\"slugs\",\"accountHash\":\"7\",\"rsn\":\"Iron Man\","
			+ "\"kind\":\"item\",\"name\":\"x\",\"quantity\":1,\"capturedAt\":\"" + NOW + "\","
			+ "\"events\":[\"my-bingo-ab12\"]}").getBytes());
		Files.write(new File(dir, "slugs.png").toPath(), PNG);
		Files.write(new File(dir, "short.json").toPath(), ("{\"id\":\"short\",\"accountHash\":\"7\",\"rsn\":\"Iron Man\","
			+ "\"kind\":\"item\",\"name\":\"x\",\"quantity\":1,\"capturedAt\":\"" + NOW + "\","
			+ "\"events\":[42]}").getBytes());

		SubmissionQueue reopened = open();

		assertEquals(List.of(entry("a", NOW, BINGO)), reopened.due(HASH, NOW));
		assertEquals(Set.of("a.json", "a.png"), Set.of(dir.list()));
	}

	@Test
	public void removesOrphanedFilesAtStart() throws IOException
	{
		queue.add(entry("a", NOW, BINGO), PNG);
		Files.write(new File(dir, "orphan.png").toPath(), PNG);
		Files.write(new File(dir, "half.json.tmp").toPath(), new byte[]{'{'});
		Files.write(new File(dir, "broken.json").toPath(), "not json".getBytes());

		SubmissionQueue reopened = open();

		assertEquals(1, reopened.due(HASH, NOW).size());
		assertEquals(Set.of("a.json", "a.png"), Set.of(dir.list()));
		assertTrue(new File(dir, "a.png").exists());
	}
}

package com.friendscape;

import com.google.gson.Gson;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class SubmissionResponseTest
{
	private static final Map<Integer, String> NAMES = Map.of(111111, "Bingo A", 222222, "Bingo B");

	private static QueuedSubmission entry(String kind, String name)
	{
		return new QueuedSubmission("id", "7", "Iron Man", kind, 11286, name, 1, "2026-11-03T12:00:00Z", List.of(111111, 222222));
	}

	private static List<ProblemNotices.Notice> notices(String events, String kind, boolean chatOnCounted)
	{
		SubmissionResponse response = new Gson().fromJson("{\"rsn\":\"Iron Man\",\"duplicate\":false,\"events\":["
			+ events + "]}", SubmissionResponse.class);
		return response.notices(entry(kind, "Draconic visage"), NAMES, chatOnCounted);
	}

	private static ProblemNotices.Notice quiet(String text)
	{
		return new ProblemNotices.Notice(text, false);
	}

	@Test
	public void namesTheEventItCountedFor()
	{
		assertEquals(List.of(quiet("Draconic visage counted for Bingo A.")),
			notices("{\"number\":111111,\"status\":\"counted\"},{\"number\":222222,\"status\":\"ended\"}", "item", true));
	}

	@Test
	public void givesOneLineNamingTheCountWhenSeveralEventsCountIt()
	{
		assertEquals(List.of(quiet("Draconic visage counted for 2 Events.")),
			notices("{\"number\":111111,\"status\":\"counted\"},{\"number\":222222,\"status\":\"counted\"}", "item", true));
	}

	@Test
	public void callsAClogSlotASlot()
	{
		assertEquals(List.of(quiet("New collection log slot (Draconic visage) counted for Bingo A.")),
			notices("{\"number\":111111,\"status\":\"counted\"}", "clog_slot", true));
	}

	@Test
	public void keepsQuietOnCountedWhenTheSettingIsOff()
	{
		assertEquals(List.of(), notices("{\"number\":111111,\"status\":\"counted\"}", "item", false));
	}

	@Test
	public void tellsOfReviewAndShowsARejectionReasonInRed()
	{
		assertEquals(List.of(
				quiet("Draconic visage is waiting for review in Bingo A."),
				new ProblemNotices.Notice("Draconic visage was rejected in Bingo B: Grace window has passed", true)),
			notices("{\"number\":111111,\"status\":\"pending\"},"
				+ "{\"number\":222222,\"status\":\"rejected\",\"reason\":\"Grace window has passed\"}", "item", false));
	}

	@Test
	public void namesAnEventDiscoveryDoesNotKnowByItsNumber()
