package com.friendscape;

import com.google.gson.Gson;
import java.io.IOException;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BooleanSupplier;
import okhttp3.HttpUrl;
import okhttp3.Interceptor;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Response;
import okhttp3.ResponseBody;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class SubmissionSenderTest
{
	private static final Instant NOW = Instant.parse("2026-11-03T12:00:00Z");
	private static final long HASH = 7L;
	private static final Gson GSON = new Gson();

	@Rule
	public TemporaryFolder folder = new TemporaryFolder();

	private final List<ProblemNotices.Notice> told = new CopyOnWriteArrayList<>();
	private final AtomicInteger changes = new AtomicInteger();
	private volatile int answerCode = 200;
	private volatile String answer = "{\"events\":[{\"number\":123456,\"status\":\"counted\"}]}";
	private SubmissionQueue queue;

	@Before
	public void setUp() throws IOException
	{
		queue = SubmissionQueue.open(folder.newFolder("submissions"), GSON);
	}

	private SubmissionSender sender()
	{
		Interceptor fake = chain -> new Response.Builder()
			.request(chain.request())
			.protocol(Protocol.HTTP_1_1)
			.code(answerCode)
			.message("fake")
			.body(ResponseBody.create(MediaType.get("application/json"), answer))
			.build();
		FriendscapeApi api = new FriendscapeApi(new OkHttpClient.Builder().addInterceptor(fake).build(), GSON,
			HttpUrl.get("https://friendscape.test/api/"), () -> true);
		return new SubmissionSender(queue, api, new SubmissionSender.Listener()
		{
			@Override
			public void tell(ProblemNotices.Notice notice)
			{
				told.add(notice);
			}

			@Override
			public void queueChanged()
			{
				changes.incrementAndGet();
			}
		});
	}

	private static QueuedSubmission entry(String id, Instant capturedAt)
	{
		return new QueuedSubmission(id, Long.toString(HASH), "Iron Man", "item", 11286, "Draconic visage", 1,
			capturedAt.toString(), List.of(123456));
	}

	/** Flushes, then waits until the send settled as {@code settled} says. */
	private void flush(SubmissionSender sender, BooleanSupplier settled) throws InterruptedException
	{
		sender.flush(HASH, new SubmissionSender.Context(Set.of(), Map.of(123456, "Bingo"), true), NOW);
		for (int i = 0; i < 200 && !settled.getAsBoolean(); i++)
		{
			Thread.sleep(10);
		}
		assertTrue("settled", settled.getAsBoolean());
	}

	@Test
	public void sendsAndForgetsAnAnsweredSubmission() throws Exception
	{
		SubmissionSender sender = sender();
		sender.add(List.of(entry("a", NOW)), new byte[]{1});

		flush(sender, () -> !told.isEmpty());

		assertEquals(Map.of(), queue.waiting());
		assertEquals(List.of(new ProblemNotices.Notice("Draconic visage counted for Bingo.", false)), told);
		assertTrue(changes.get() >= 2);
	}

	@Test
	public void keepsASubmissionTheServerDidNotAnswer() throws Exception
	{
		answerCode = 502;
		SubmissionSender sender = sender();
		sender.add(List.of(entry("a", NOW)), new byte[]{1});

		flush(sender, () -> !queue.due(HASH, NOW.plus(SubmissionQueue.FIRST_RETRY)).isEmpty());

		assertEquals(Map.of("7", Map.of(123456, 1)), queue.waiting());
		assertEquals("backing off", List.of(), queue.due(HASH, NOW));
		assertEquals(1, queue.due(HASH, NOW.plus(SubmissionQueue.FIRST_RETRY)).size());
		assertEquals(List.of(), told);
	}

	@Test
	public void dropsARefusedSubmissionAndSaysSo() throws Exception
	{
		answerCode = 400;
		SubmissionSender sender = sender();
		sender.add(List.of(entry("a", NOW)), new byte[]{1});

		flush(sender, () -> !told.isEmpty());

		assertEquals(Map.of(), queue.waiting());
		assertEquals(List.of(new ProblemNotices.Notice(
			"Friendscape refused Draconic visage. Upload a screenshot on the event page to claim it.", true)), told);
	}

	@Test
	public void tellsOfSubmissionsTheFullQueuePushesOut() throws Exception
	{
		SubmissionSender sender = sender();
		for (int i = 0; i <= SubmissionQueue.CAP; i++)
		{
			sender.add(List.of(entry("e" + i, NOW.plusSeconds(i))), new byte[]{1});
		}

		assertEquals(List.of(new ProblemNotices.Notice(
			"The send queue is full, so Draconic visage was taken out of it. Upload it on the event page.", true)), told);
		assertEquals(new EventCard.Queued(SubmissionQueue.CAP, 1), sender.queued(HASH).get(123456));
	}

	@Test
	public void prunesWhatNoDiscoveredEventCanCount() throws Exception
	{
		SubmissionSender sender = sender();
		sender.add(List.of(entry("a", NOW)), new byte[]{1});
		DiscoveryResponse discovery = GSON.fromJson("{\"events\":[{\"number\":123456,\"phase\":\"ended\","
			+ "\"endsAt\":\"2026-11-03T11:00:00Z\",\"graceWindowSeconds\":3600}]}", DiscoveryResponse.class);

		sender.prune(HASH, discovery, NOW);

		assertEquals(Map.of(), queue.waiting());
		assertEquals(Map.of(), sender.queued(HASH));
	}

	@Test
	public void keepsWhatADiscoveredEventMayStillCount() throws Exception
	{
		SubmissionSender sender = sender();
		sender.add(List.of(entry("a", NOW)), new byte[]{1});
		DiscoveryResponse discovery = GSON.fromJson("{\"events\":[{\"number\":123456,\"phase\":\"live\","
			+ "\"endsAt\":\"2026-11-04T12:00:00Z\",\"graceWindowSeconds\":3600}]}", DiscoveryResponse.class);

		sender.prune(HASH, discovery, NOW);

		assertEquals(new EventCard.Queued(1, 0), sender.queued(HASH).get(123456));
	}
}

package com.friendscape;

import com.google.gson.Gson;
import java.util.List;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class TeamCompletionsTest
{
	private static final Gson GSON = new Gson();

	private final TeamCompletions completions = new TeamCompletions();

	/**
	 * A Live bingo Event with Tile 1 (one Tier) and Tile 2 (three Tiers); Red is the player's Team,
	 * Blue a rival. Each tier array gives the Tier reached per position, 0 for none.
	 */
	private static DiscoveryResponse discovery(int[] red, int[] blue)
	{
		String json = "{\"events\":[{\"number\":123456,\"name\":\"Autumn bingo\",\"format\":\"bingo\","
			+ "\"phase\":\"live\",\"entry\":\"on_roster\",\"board\":{\"size\":2,\"tiles\":["
			+ "{\"number\":1,\"name\":\"Blood shards\",\"tiers\":1},"
			+ "{\"number\":2,\"name\":\"Vorkath\",\"tiers\":3}],\"teams\":["
			+ team(1, "Red", true, red) + "," + team(2, "Blue", false, blue) + "]}}]}";
		return GSON.fromJson(json, DiscoveryResponse.class);
	}

	private static String team(int id, String name, boolean mine, int[] tiers)
	{
		StringBuilder tiles = new StringBuilder();
		for (int i = 0; i < 4; i++)
		{
			int tier = i < tiers.length ? tiers[i] : 0;
			tiles.append(i == 0 ? "" : ",").append("{\"state\":\"open\",\"tier\":")
				.append(tier == 0 ? "null" : tier).append(",\"fill\":0}");
		}
		return "{\"team\":" + id + ",\"name\":\"" + name + "\",\"rank\":1,\"of\":2,\"points\":0,"
			+ "\"mine\":" + mine + ",\"tiles\":[" + tiles + "]}";
	}

	@Test
	public void saysNothingOnTheFirstLookAtABoard()
	{
		assertTrue(completions.check(discovery(new int[]{1, 2}, new int[]{}), Set.of()).isEmpty());
	}

	@Test
	public void namesATileTheTeamCompleted()
	{
		completions.check(discovery(new int[]{}, new int[]{}), Set.of());

		List<String> told = completions.check(discovery(new int[]{1}, new int[]{}), Set.of());

		assertEquals(List.of("Red completed Tile 1 (Blood shards) in Autumn bingo."), told);
	}

	@Test
	public void namesATierReachedOnATileWithSeveral()
	{
		completions.check(discovery(new int[]{0, 1}, new int[]{}), Set.of());

		List<String> told = completions.check(discovery(new int[]{0, 2}, new int[]{}), Set.of());

		assertEquals(List.of("Red reached Tier 2 of 3 on Tile 2 (Vorkath) in Autumn bingo."), told);
	}

	@Test
	public void namesOnlyTheTopTierWhenSeveralCameAtOnce()
	{
		completions.check(discovery(new int[]{}, new int[]{}), Set.of());

		List<String> told = completions.check(discovery(new int[]{0, 3}, new int[]{}), Set.of());

		assertEquals(List.of("Red reached Tier 3 of 3 on Tile 2 (Vorkath) in Autumn bingo."), told);
	}

	@Test
	public void ignoresRivalTeamsAndReversals()
	{
		completions.check(discovery(new int[]{1}, new int[]{}), Set.of());

		assertTrue(completions.check(discovery(new int[]{0}, new int[]{1, 3}), Set.of()).isEmpty());
	}

	@Test
	public void saysNothingForALeftEvent()
	{
		completions.check(discovery(new int[]{}, new int[]{}), Set.of());

		assertTrue(completions.check(discovery(new int[]{1}, new int[]{}), Set.of(123456)).isEmpty());
	}

	@Test
	public void startsOverAfterAReset()
	{
		completions.check(discovery(new int[]{}, new int[]{}), Set.of());
		completions.reset();

		assertTrue(completions.check(discovery(new int[]{1}, new int[]{}), Set.of()).isEmpty());
	}
}

package com.friendscape;

import com.google.gson.Gson;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class WatchListTest
{
	private static final Gson GSON = new Gson();

	/** A Live bingo watching {@code watch}, unless {@code extra} overrides its fields. */
	private static String event(int number, String watch, String extra)
	{
		return "{\"number\":" + number + ",\"name\":\"Bingo " + number + "\",\"format\":\"bingo\",\"phase\":\"live\","
			+ "\"entry\":\"on_roster\",\"watch\":" + watch + (extra.isEmpty() ? "" : "," + extra) + "}";
	}

	private static WatchList watch(Set<Integer> left, String... events)
	{
		DiscoveryResponse discovery = GSON.fromJson("{\"rsn\":\"Iron Man\",\"events\":["
			+ String.join(",", events) + "]}", DiscoveryResponse.class);
		return WatchList.of(discovery, left);
	}

	private static final String VISAGE = "{\"items\":[{\"id\":11286,\"name\":\"Draconic visage\"}],\"clogSlots\":false}";
	private static final String SNAKELING = "{\"items\":[{\"id\":12921,\"name\":\"Pet snakeling\"}],\"clogSlots\":true}";

	@Test
	public void namesTheEventsAnItemIsWatchedIn()
	{
		WatchList list = watch(Set.of(), event(111111, VISAGE, ""), event(222222, VISAGE, ""), event(333333, SNAKELING, ""));

		assertEquals(Set.of(111111, 222222), list.eventsFor(11286));
		assertEquals(Set.of(), list.eventsFor(4151));
		assertEquals(Set.of(333333), list.clogSlotEvents());
	}

	@Test
	public void findsAWatchedItemByTheNameChatUses()
	{
		WatchList list = watch(Set.of(), event(111111, SNAKELING, ""));

		assertEquals(Integer.valueOf(12921), list.idForName("pet snakeling"));
		assertNull(list.idForName("Pet kraken"));
	}

	@Test
	public void cannotPinANameTwoWatchedIdsShare()
	{
		WatchList list = watch(Set.of(),
			event(111111, "{\"items\":[{\"id\":1,\"name\":\"Dossier\"},{\"id\":2,\"name\":\"Dossier\"}]}", ""));

		assertNull(list.idForName("Dossier"));
	}

	@Test
	public void watchesOnlyLiveEventsStillOnTheRosterAndNotLeft()
	{
		WatchList list = watch(Set.of(100001),
			event(100001, VISAGE, ""),
			event(100002, VISAGE, "\"entry\":\"removed\""),
			event(100003, VISAGE, "\"phase\":\"scheduled\""),
			event(100004, VISAGE, "\"phase\":\"ended\""),
			event(100005, VISAGE, "\"entry\":\"held\""));

		// A held entry's Submissions are kept, and count if the identity check settles in its favour
		assertEquals(Set.of(100005), list.eventsFor(11286));
	}

	@Test
	public void watchesNothingWithoutAWatchFromTheServer()
	{
		WatchList list = watch(Set.of(), "{\"number\":111111,\"phase\":\"live\",\"entry\":\"on_roster\"}");

		assertEquals(Set.of(), list.eventsFor(11286));
		assertEquals(Set.of(), list.clogSlotEvents());
		assertEquals(Set.of(), WatchList.of(null, Set.of()).clogSlotEvents());
	}
}

package com.friendscape;

import java.util.EnumSet;
import net.runelite.api.WorldType;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class WorldFilterTest
{
	@Test
	public void tracksNormalWorlds()
	{
		assertTrue(WorldFilter.isTracked(EnumSet.noneOf(WorldType.class)));
		assertTrue(WorldFilter.isTracked(EnumSet.of(WorldType.MEMBERS)));
		assertTrue(WorldFilter.isTracked(EnumSet.of(WorldType.MEMBERS, WorldType.SKILL_TOTAL)));
		assertTrue(WorldFilter.isTracked(EnumSet.of(WorldType.MEMBERS, WorldType.PVP, WorldType.HIGH_RISK)));
	}

	@Test
	public void excludesLeagues()
	{
		assertFalse(WorldFilter.isTracked(EnumSet.of(WorldType.MEMBERS, WorldType.SEASONAL)));
	}

	@Test
	public void excludesSpecialWorlds()
	{
		for (WorldType type : new WorldType[]{
			WorldType.DEADMAN,
			WorldType.FRESH_START_WORLD,
			WorldType.TOURNAMENT_WORLD,
			WorldType.BETA_WORLD,
			WorldType.NOSAVE_MODE,
			WorldType.QUEST_SPEEDRUNNING,
			WorldType.PVP_ARENA,
			WorldType.LAST_MAN_STANDING,
		})
		{
			assertFalse(type.name(), WorldFilter.isTracked(EnumSet.of(WorldType.MEMBERS, type)));
		}
	}

	@Test
	public void excludesUnknownWorld()
	{
		assertFalse(WorldFilter.isTracked(null));
	}
}

package com.friendscape;

import java.time.Instant;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class XpTrackerTest
{
	private static final Instant LOGIN = Instant.parse("2026-11-03T00:00:00Z");

	private final XpTracker tracker = new XpTracker();

	private static Instant after(int seconds)
	{
		return LOGIN.plusSeconds(seconds);
	}

	@Test
	public void sendsEverySkillAndTheirSumAsOverallAtLogin()
	{
		Map<String, Long> sent = tracker.takeAll(Map.of("attack", 100L, "slayer", 2_000L), LOGIN);

		assertEquals(Map.of("attack", 100L, "slayer", 2_000L, "overall", 2_100L), sent);
	}

	@Test
	public void ignoresStatChangesBeforeTheLoginReading()
	{
		tracker.observe("attack", 500L);

		assertFalse(tracker.due(after(120)));
	}

	@Test
	public void sendsOnlyChangedSkillsPlusOverall()
	{
		tracker.takeAll(Map.of("attack", 100L, "slayer", 2_000L), LOGIN);

		tracker.observe("slayer", 2_050L);

		assertEquals(Map.of("slayer", 2_050L, "overall", 2_150L), tracker.takeChanged(after(60)));
	}

	@Test
	public void ignoresAnUnchangedValue()
	{
		// Boosts and drains fire StatChanged with the same XP
		tracker.takeAll(Map.of("attack", 100L), LOGIN);

		tracker.observe("attack", 100L);

		assertFalse(tracker.due(after(120)));
		assertTrue(tracker.takeChanged(after(120)).isEmpty());
	}

	@Test
	public void sendsAtMostOncePerMinuteWhileXpChanges()
	{
		tracker.takeAll(Map.of("attack", 100L), LOGIN);

		tracker.observe("attack", 150L);
		assertFalse(tracker.due(after(59)));
		assertTrue(tracker.due(after(60)));

		tracker.takeChanged(after(60));
		tracker.observe("attack", 200L);
		assertFalse(tracker.due(after(119)));
		assertTrue(tracker.due(after(120)));
	}

	@Test
	public void changesNothingAfterSendingThem()
	{
		tracker.takeAll(Map.of("attack", 100L), LOGIN);
		tracker.observe("attack", 150L);

		tracker.takeChanged(after(60));

		assertFalse(tracker.due(after(600)));
	}

	@Test
	public void forgetsEverythingOnReset()
	{
		tracker.takeAll(Map.of("attack", 100L), LOGIN);
		tracker.observe("attack", 150L);

		tracker.reset();
		tracker.observe("attack", 200L);

		assertTrue(tracker.takeChanged(after(600)).isEmpty());
	}
}
